}
.vignette::after{
  content:"";position:absolute;inset:0;opacity:.07;pointer-events:none;
  background:repeating-linear-gradient(0deg,transparent 0 2px,rgba(255,255,255,.22) 3px,transparent 4px 6px);
  mix-blend-mode:overlay;
}
#damage-flash{
  position:absolute;inset:0;z-index:8;pointer-events:none;opacity:0;
  background:
    radial-gradient(ellipse at center,transparent 28%,rgba(190,10,30,.5) 82%,rgba(255,20,45,.75) 110%);
  mix-blend-mode:screen;
  transition:opacity .09s linear;
}
#low-health{
  position:absolute;inset:0;z-index:7;pointer-events:none;opacity:0;
  background:radial-gradient(ellipse at center,transparent 45%,rgba(150,4,20,.5) 100%);
  animation:lowPulse 1.1s ease-in-out infinite;
}
#low-health.on{opacity:1}
@keyframes lowPulse{0%,100%{opacity:.28}50%{opacity:.72}}
#descent-streaks{
  position:absolute;inset:0;z-index:3;pointer-events:none;opacity:0;transition:opacity .35s;
  background:repeating-linear-gradient(96deg,transparent 0 18px,rgba(160,220,255,.14) 19px,transparent 20px 47px);
  mask-image:radial-gradient(ellipse at center,transparent 20%,black 90%);
  animation:streakMove .32s linear infinite;
}
#descent-streaks.on{opacity:.55}
@keyframes streakMove{from{background-position:0 0}to{background-position:0 90px}}

/* ---------- HUD ---------- */
#hud{position:absolute;inset:0;z-index:5;pointer-events:none;opacity:0;transition:opacity .45s}
#hud.on{opacity:1}
.hud-corner{position:absolute;top:clamp(14px,2.4vw,28px)}
.hud-left{left:clamp(14px,2.4vw,30px);width:min(260px,30vw)}
.hud-right{right:clamp(14px,2.4vw,30px);text-align:right;min-width:128px}
.hunter-tag{
  display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:.24em;color:var(--gold);
  text-transform:uppercase;margin-bottom:9px;text-shadow:0 0 14px rgba(226,181,103,.4)
}
.hunter-tag #stat-damage{margin-left:auto;color:var(--bone-dim);font-size:8px;letter-spacing:.12em}
.mini-sigil{
  width:11px;height:11px;display:inline-block;border:1px solid var(--gold);transform:rotate(45deg);
  position:relative;box-shadow:0 0 10px rgba(226,181,103,.35)
}
.mini-sigil::after{content:"";position:absolute;inset:3px;background:var(--gold);opacity:.65}
.bar-label{display:flex;justify-content:space-between;align-items:baseline;font-size:9px;letter-spacing:.22em;color:var(--bone-dim);margin-bottom:5px}
.bar-label span:last-child{color:var(--bone);font-size:11px;letter-spacing:.05em}
.health-track{
  height:10px;position:relative;background:rgba(255,255,255,.06);
  border:1px solid rgba(226,181,103,.27);clip-path:polygon(0 0,100% 0,calc(100% - 7px) 100%,0 100%);
  overflow:hidden
}
#hp-fill{
  position:absolute;inset:0;width:100%;transform-origin:left;
  background:linear-gradient(90deg,var(--blood-deep),var(--blood) 58%,#ff7d76);
  box-shadow:0 0 18px rgba(255,61,80,.45);
  transition:transform .16s ease-out,filter .2s
}
#hp-fill.low{filter:saturate(1.5) brightness(1.25)}
.bar-ticks{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 calc(10% - 1px),rgba(0,0,0,.55) calc(10% - 1px) 10%)}
.sub-row{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.14em;color:var(--bone-dim);margin-top:7px}
#dash-label.ready{color:var(--teal)}
#dash-pips{display:flex;gap:4px;align-items:center}
#dash-pips i{display:block;width:20px;height:3px;background:rgba(93,240,213,.2);transition:background .1s}
#dash-pips.ready i{background:var(--teal);box-shadow:0 0 8px rgba(93,240,213,.8)}
#dash-pips i:nth-child(2){display:none}

.depth-display{position:absolute;left:50%;top:clamp(10px,1.7vw,20px);transform:translateX(-50%);text-align:center;width:min(540px,65vw)}
#level-label{font-size:9px;letter-spacing:.34em;color:var(--bone-dim);text-transform:uppercase;white-space:nowrap;text-shadow:0 1px 8px #000}
.floor-row{display:flex;align-items:center;justify-content:center;gap:12px;margin-top:1px;height:54px}
.floor-word{font-size:8px;letter-spacing:.3em;color:var(--gold);writing-mode:vertical-rl;transform:rotate(180deg);opacity:.7}
#floor-num{
  font-family:var(--serif);font-size:clamp(34px,4.2vw,54px);line-height:1;letter-spacing:.02em;
  color:var(--bone);text-shadow:0 0 26px rgba(226,181,103,.2),0 2px 4px #000;font-variant-numeric:tabular-nums
}
#floor-num.boss{color:var(--blood);text-shadow:0 0 30px rgba(255,61,80,.65),0 2px 4px #000;animation:bossNum 1.4s ease-in-out infinite}
@keyframes bossNum{0%,100%{filter:brightness(1)}50%{filter:brightness(1.35)}}
.floor-pips{display:flex;gap:5px;justify-content:center;margin-top:4px}
.floor-pips i{width:22px;height:3px;background:rgba(233,227,211,.13);position:relative;transition:background .25s,box-shadow .25s}
.floor-pips i.done{background:var(--gold);box-shadow:0 0 8px rgba(226,181,103,.5)}
.floor-pips i.current{background:var(--gold-hot);box-shadow:0 0 10px rgba(255,213,141,.9)}
.floor-pips.boss i.done{background:var(--blood);box-shadow:0 0 8px rgba(255,61,80,.6)}
#objective{margin-top:8px;font-size:9px;letter-spacing:.28em;color:var(--teal);text-transform:uppercase;text-shadow:0 0 12px rgba(93,240,213,.5)}
#objective.alert{color:var(--blood);text-shadow:0 0 12px rgba(255,61,80,.6)}

.stat{display:flex;align-items:baseline;justify-content:flex-end;gap:10px;margin-bottom:5px}
.stat-label{font-size:8px;letter-spacing:.24em;color:var(--bone-dim)}
.stat span:last-child{font-family:var(--serif);font-size:27px;line-height:1;color:var(--bone);min-width:38px;text-align:right;text-shadow:0 2px 5px #000}
#hostile-count{color:var(--blood)}
#hostile-count.clear{color:var(--teal)}

.crosshair{position:absolute;left:50%;top:50%;width:38px;height:38px;transform:translate(-50%,-50%);z-index:6;filter:drop-shadow(0 0 3px rgba(0,0,0,.9))}
.crosshair .ch{position:absolute;background:rgba(233,227,211,.86);transition:transform .1s,background .1s}
.crosshair .ch-n{left:18px;top:0;width:2px;height:10px}
.crosshair .ch-s{left:18px;bottom:0;width:2px;height:10px}
.crosshair .ch-e{right:0;top:18px;width:10px;height:2px}
.crosshair .ch-w{left:0;top:18px;width:10px;height:2px}
.crosshair .ch-dot{position:absolute;left:17px;top:17px;width:4px;height:4px;border-radius:50%;background:var(--gold-hot);box-shadow:0 0 8px rgba(255,213,141,.8)}
.crosshair.enemy .ch{background:var(--blood)}
.crosshair.enemy .ch-dot{background:var(--blood);box-shadow:0 0 10px var(--blood)}
.crosshair.fire .ch-n{transform:translateY(-4px)}
.crosshair.fire .ch-s{transform:translateY(4px)}
.crosshair.fire .ch-e{transform:translateX(4px)}
.crosshair.fire .ch-w{transform:translateX(-4px)}
.crosshair.reload .ch{opacity:.35}

#hitmarker{position:absolute;left:50%;top:50%;width:30px;height:30px;transform:translate(-50%,-50%) rotate(45deg);opacity:0;z-index:7}
#hitmarker.show{animation:hitPop .17s ease-out}
#hitmarker.head span{background:var(--gold-hot)!important}
#hitmarker span{position:absolute;background:#fff;box-shadow:0 0 6px rgba(255,255,255,.9)}
#hitmarker span:nth-child(1){left:14px;top:0;width:2px;height:8px}
#hitmarker span:nth-child(2){left:14px;bottom:0;width:2px;height:8px}
#hitmarker span:nth-child(3){top:14px;left:0;width:8px;height:2px}
#hitmarker span:nth-child(4){top:14px;right:0;width:8px;height:2px}
@keyframes hitPop{0%{opacity:1;transform:translate(-50%,-50%) rotate(45deg) scale(.6)}100%{opacity:0;transform:translate(-50%,-50%) rotate(45deg) scale(1.25)}}

.ammo-wrap{position:absolute;right:clamp(14px,2.4vw,30px);bottom:clamp(20px,3.2vw,38px);text-align:right;min-width:190px}
.weapon-name{font-size:9px;letter-spacing:.24em;color:var(--bone-dim);margin-bottom:8px}
.weapon-name span{color:var(--gold);opacity:.7;margin-left:5px}
.ammo-pips{display:flex;gap:5px;justify-content:flex-end;height:17px;align-items:flex-end}
.ammo-pips i{
  display:block;width:8px;height:17px;background:linear-gradient(180deg,var(--gold-hot),#a97b35);
  clip-path:polygon(50% 0,100% 24%,100% 100%,0 100%,0 24%);box-shadow:0 0 7px rgba(255,213,141,.35);
  transition:opacity .12s,transform .12s
}
.ammo-pips i.spent{opacity:.14;transform:translateY(3px);box-shadow:none}
#reload-label{font-size:8px;letter-spacing:.25em;color:var(--teal);margin-top:7px;height:11px}
#reload-label.reloading{color:var(--gold);animation:blink .55s steps(2,end) infinite}
@keyframes blink{50%{opacity:.35}}

.ability-hints{
  position:absolute;left:50%;bottom:clamp(17px,2.6vw,30px);transform:translateX(-50%);
  display:flex;gap:22px;font-size:8px;letter-spacing:.13em;color:rgba(233,227,211,.38);white-space:nowrap
}
kbd{
  display:inline-block;padding:2px 5px;border:1px solid rgba(233,227,211,.26);border-radius:2px;
  color:var(--bone);font-family:var(--mono);font-size:8px;letter-spacing:.06em;background:rgba(255,255,255,.035)
}
#reticle-hint{
  position:absolute;left:50%;top:calc(50% + 40px);transform:translateX(-50%);font-size:8px;letter-spacing:.22em;
  color:rgba(233,227,211,.55);opacity:0;transition:opacity .3s;white-space:nowrap
}
#reticle-hint.on{opacity:1;animation:blink 1.6s ease-in-out infinite}

#boss-ui{
  position:absolute;left:50%;bottom:clamp(42px,6.6vw,78px);transform:translateX(-50%);
  width:min(660px,74vw);display:none
}
#boss-ui.show{display:block;animation:bossIn .5s ease-out}
@keyframes bossIn{from{opacity:0;transform:translateX(-50%) translateY(10px)}to{opacity:1;transform:translateX(-50%) translateY(0)}}
.boss-top{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:7px}
#boss-name{font-family:var(--serif);font-size:16px;letter-spacing:.18em;color:var(--bone);text-shadow:0 0 18px rgba(255,61,80,.35)}
#boss-hp-text{font-size:9px;letter-spacing:.16em;color:var(--blood)}
.boss-track{height:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,61,80,.4);position:relative;overflow:hidden}
#boss-fill{position:absolute;inset:0;background:linear-gradient(90deg,#5c0712,#d5142e 65%,#ff6a5e);transform-origin:left;box-shadow:0 0 20px rgba(255,61,80,.4)}
.boss-notches{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 calc(10% - 1px),rgba(0,0,0,.55) calc(10% - 1px) 10%)}
#boss-state{text-align:center;margin-top:6px;font-size:8px;letter-spacing:.3em;color:var(--blood);text-transform:uppercase}

#interact{
  position:absolute;left:50%;bottom:clamp(96px,14vw,150px);transform:translateX(-50%);
  display:none;align-items:center;gap:12px;padding:10px 18px;background:rgba(4,7,10,.72);
  border:1px solid rgba(226,181,103,.4);backdrop-filter:blur(6px)
}
#interact.show{display:flex}
#interact kbd{width:28px;height:28px;display:grid;place-items:center;font-size:12px;border-color:var(--gold);color:var(--gold)}
#interact span{font-size:9px;letter-spacing:.2em;color:var(--bone)}
.interact-track{width:90px;height:4px;background:rgba(255,255,255,.12);overflow:hidden}
#interact-fill{height:100%;width:0%;background:linear-gradient(90deg,var(--gold),#fff3c4);box-shadow:0 0 10px var(--gold)}

#toast-layer{position:absolute;left:50%;top:22%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:8px}
.toast{
  font-size:10px;letter-spacing:.3em;color:var(--bone);text-transform:uppercase;padding:8px 20px;
  background:linear-gradient(90deg,transparent,rgba(5,8,12,.76) 15%,rgba(5,8,12,.76) 85%,transparent);
  animation:toastIn 2.2s ease-out forwards;white-space:nowrap;text-shadow:0 0 14px rgba(226,181,103,.35)
}
.toast.gold{color:var(--gold-hot)}
.toast.red{color:var(--blood)}
@keyframes toastIn{0%{opacity:0;transform:translateY(8px)}12%{opacity:1;transform:translateY(0)}75%{opacity:1}100%{opacity:0;transform:translateY(-6px)}}

/* ---------- screens ---------- */
.screen{
  position:absolute;inset:0;z-index:20;display:flex;align-items:center;justify-content:flex-start;
  padding:clamp(24px,5vw,76px);overflow:hidden;
  background:
    linear-gradient(90deg,rgba(3,5,8,.94) 0%,rgba(3,5,8,.8) 32%,rgba(3,5,8,.25) 64%,rgba(3,5,8,.04) 100%),
    radial-gradient(ellipse at 66% 46%,rgba(15,18,24,.05),rgba(2,3,5,.55) 78%);
}
#start-screen{transition:opacity .8s ease,visibility .8s}
#start-screen.closing{opacity:0;visibility:hidden}
.menu-frame{position:relative;z-index:2;width:min(660px,74vw);animation:menuIn 1.1s cubic-bezier(.2,.8,.2,1) both}
@keyframes menuIn{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
.eyebrow{display:flex;align-items:center;gap:14px;font-size:9px;letter-spacing:.34em;color:var(--gold);text-transform:uppercase;margin-bottom:19px;text-shadow:0 0 12px rgba(226,181,103,.35)}
.eyebrow span{display:block;width:34px;height:1px;background:linear-gradient(90deg,transparent,var(--gold))}
.eyebrow span:last-child{background:linear-gradient(90deg,var(--gold),transparent)}
.eyebrow.danger{color:var(--blood);text-shadow:0 0 12px rgba(255,61,80,.4)}
.eyebrow.danger span{background:linear-gradient(90deg,transparent,var(--blood))}
.eyebrow.danger span:last-child{background:linear-gradient(90deg,var(--blood),transparent)}
.menu-frame h1{
  margin:0;font-family:var(--serif);font-weight:400;text-transform:uppercase;
  font-size:clamp(50px,7.4vw,105px);line-height:.82;letter-spacing:.015em;
  background:linear-gradient(180deg,#fffbf0 0%,var(--bone) 45%,#8f846e 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 4px 18px rgba(0,0,0,.9));text-shadow:0 0 50px rgba(226,181,103,.14)
}
.menu-frame h1 small{display:block;font-size:.26em;letter-spacing:.56em;color:var(--gold);-webkit-text-fill-color:var(--gold);margin-bottom:6px;margin-left:5px}
.menu-frame h1 em{display:block;font-style:italic;letter-spacing:.02em;background:linear-gradient(180deg,#ffe8bd,var(--gold) 66%,#8e602b);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 24px rgba(226,181,103,.2))}
.title-rule{display:flex;align-items:center;gap:7px;margin:24px 0 18px;width:min(470px,100%)}
.title-rule i{height:1px;flex:1;background:linear-gradient(90deg,transparent,rgba(226,181,103,.55))}
.title-rule i:last-child{background:linear-gradient(90deg,rgba(226,181,103,.55),transparent)}
.title-rule b{width:9px;height:9px;border:1px solid var(--gold);transform:rotate(45deg);box-shadow:0 0 14px rgba(226,181,103,.35)}
.tagline{font-family:var(--serif);font-size:clamp(15px,1.55vw,19px);line-height:1.55;color:#cfc7b5;margin:0 0 26px;letter-spacing:.02em;max-width:540px;text-shadow:0 2px 8px #000}
.tagline strong{color:var(--gold-hot);font-weight:400}
.briefing{display:flex;gap:0;margin:0 0 30px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);width:min(540px,100%)}
.briefing div{display:flex;align-items:center;gap:11px;padding:13px 18px 13px 0;flex:1;border-right:1px solid var(--line)}
.briefing div:last-child{border-right:0}
.briefing b{font-family:var(--serif);font-size:13px;font-weight:400;color:var(--gold);letter-spacing:.04em}
.briefing span{font-size:8px;line-height:1.55;letter-spacing:.16em;color:var(--bone-dim);text-transform:uppercase}

.primary{
  position:relative;display:inline-flex;align-items:center;justify-content:center;min-width:220px;padding:16px 42px;
  font-family:var(--mono);font-size:12px;letter-spacing:.42em;text-indent:.42em;color:#120d05;
  background:linear-gradient(180deg,var(--gold-hot),var(--gold) 52%,#b07d38);
  clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px);
  box-shadow:0 0 0 1px rgba(255,235,190,.25) inset,0 10px 34px rgba(0,0,0,.55),0 0 32px rgba(226,181,103,.14);
  transition:filter .15s,transform .15s;overflow:hidden
}
.primary::after{content:"";position:absolute;inset:0;background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.55) 50%,transparent 68%);transform:translateX(-120%);transition:transform .5s}
.primary:hover{filter:brightness(1.13);transform:translateY(-1px)}
.primary:hover::after{transform:translateX(120%)}
.primary:active{transform:translateY(1px)}
#start-btn{animation:startGlow 3.2s ease-in-out infinite}
@keyframes startGlow{0%,100%{box-shadow:0 0 0 1px rgba(255,235,190,.25) inset,0 10px 34px rgba(0,0,0,.55),0 0 24px rgba(226,181,103,.12)}50%{box-shadow:0 0 0 1px rgba(255,235,190,.4) inset,0 10px 34px rgba(0,0,0,.55),0 0 42px rgba(226,181,103,.34)}}
.controls-line{display:flex;gap:19px;margin-top:23px;font-size:8px;letter-spacing:.15em;color:rgba(233,227,211,.47);flex-wrap:wrap}
.controls-line kbd{margin-right:5px}
.menu-footer{position:absolute;left:clamp(24px,5vw,76px);right:clamp(24px,5vw,76px);bottom:22px;display:flex;justify-content:space-between;font-size:8px;letter-spacing:.24em;color:rgba(233,227,211,.32);z-index:2}
.menu-credit{position:absolute;right:clamp(24px,5vw,76px);bottom:48px;font-size:7px;letter-spacing:.3em;color:rgba(226,181,103,.45);transform:rotate(-90deg) translateX(100%);transform-origin:right bottom}
.menu-sigil{
  position:absolute;right:6vw;top:50%;width:min(40vw,560px);aspect-ratio:1;transform:translateY(-50%);
  border:1px solid rgba(226,181,103,.09);border-radius:50%;z-index:1;opacity:.85;
  box-shadow:0 0 80px rgba(226,181,103,.04) inset
}
.menu-sigil::before,.menu-sigil::after{content:"";position:absolute;inset:8%;border:1px solid rgba(226,181,103,.07);border-radius:50%}
.menu-sigil::after{inset:22%;border-style:dashed;animation:spin 60s linear infinite}
.menu-sigil i{position:absolute;left:50%;top:50%;width:70%;height:1px;background:linear-gradient(90deg,transparent,rgba(226,181,103,.12),transparent);transform-origin:center}
.menu-sigil i:nth-child(2){transform:rotate(60deg)}
.menu-sigil i:nth-child(3){transform:rotate(120deg)}
@keyframes spin{to{transform:rotate(360deg)}}

.hud-left,.hud-right,.depth-display,.crosshair,.ammo-wrap,.ability-hints,#boss-ui{transition:opacity .35s}
body.in-menu .hud-left,body.in-menu .hud-right,body.in-menu .depth-display,body.in-menu .crosshair,body.in-menu .ammo-wrap,body.in-menu .ability-hints,body.in-menu #boss-ui{opacity:0}

.panel{
  position:relative;z-index:2;width:min(510px,92vw);margin:auto;text-align:center;
  padding:clamp(30px,5vw,54px) clamp(24px,4vw,50px);
  background:linear-gradient(180deg,rgba(8,11,16,.94),rgba(4,6,9,.9));
  border:1px solid var(--line);
  box-shadow:0 28px 80px rgba(0,0,0,.7),0 0 0 1px rgba(0,0,0,.5) inset;
  animation:panelIn .45s cubic-bezier(.2,.8,.2,1) both
}
.panel::before,.panel::after{content:"";position:absolute;width:22px;height:22px;border:1px solid rgba(226,181,103,.4)}
.panel::before{left:-1px;top:-1px;border-right:0;border-bottom:0}
.panel::after{right:-1px;bottom:-1px;border-left:0;border-top:0}
@keyframes panelIn{from{opacity:0;transform:translateY(14px) scale(.985)}to{opacity:1;transform:none}}
.panel .eyebrow{justify-content:center}
.panel h2{
  margin:0 0 12px;font-family:var(--serif);font-weight:400;font-size:clamp(42px,6vw,68px);line-height:.95;
  letter-spacing:.04em;text-transform:uppercase;
  background:linear-gradient(180deg,#fffaf0,var(--bone) 50%,#8c806b);-webkit-background-clip:text;background-clip:text;color:transparent
}
.panel p{font-family:var(--serif);font-size:16px;line-height:1.5;color:#bdb4a2;margin:0 auto 26px;max-width:340px}
.panel .primary{display:flex;margin:0 auto 11px}
.ghost{
  display:block;margin:0 auto;padding:10px 22px;font-size:8px;letter-spacing:.3em;color:var(--bone-dim);
  border-bottom:1px solid transparent;transition:color .15s,border-color .15s
}
.ghost:hover{color:var(--bone);border-color:rgba(226,181,103,.4)}
.victory-panel h2{background:linear-gradient(180deg,#fffaf0,var(--gold-hot) 45%,#9b6c2e);-webkit-background-clip:text;background-clip:text;color:transparent}
.victory-stats{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line);margin:0 0 28px}
.victory-stats div{background:rgba(6,9,13,.86);padding:15px 10px;display:flex;flex-direction:column;gap:5px}
.victory-stats span{font-size:7px;letter-spacing:.25em;color:var(--bone-dim)}
.victory-stats b{font-family:var(--serif);font-size:25px;font-weight:400;color:var(--gold-hot)}

/* ---------- level banner ---------- */
.banner{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:15;text-align:center;
  width:min(650px,86vw);pointer-events:none;
  animation:bannerFade 3.4s ease forwards
}
@keyframes bannerFade{0%{opacity:0}12%{opacity:1}78%{opacity:1}100%{opacity:0}}
.banner-line{height:1px;background:linear-gradient(90deg,transparent,rgba(226,181,103,.6),transparent);margin:13px 0}
.banner-kicker{font-size:8px;letter-spacing:.5em;color:var(--gold)}
.banner-title{font-family:var(--serif);font-size:clamp(44px,7vw,82px);line-height:1;text-transform:uppercase;letter-spacing:.03em;background:linear-gradient(180deg,#fffaf0,var(--bone) 55%,#8f846e);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 5px 20px rgba(0,0,0,.8))}
.banner-sub{font-size:10px;letter-spacing:.42em;color:var(--bone-dim);margin-top:7px}
.banner.boss .banner-kicker,.banner.boss .banner-sub{color:var(--blood)}
.banner.boss .banner-title{background:linear-gradient(180deg,#fff5f5,#ff6d6d 55%,#7c0718);-webkit-background-clip:text;background-clip:text;color:transparent}

/* ---------- touch ---------- */
#touch-controls{display:none;position:absolute;inset:0;z-index:9;pointer-events:none}
#touch-stick{position:absolute;left:26px;bottom:110px;width:104px;height:104px;border:1px solid rgba(233,227,211,.2);border-radius:50%;background:rgba(5,8,12,.3);pointer-events:auto}
#touch-stick i{position:absolute;left:50%;top:50%;width:38px;height:38px;border-radius:50%;background:rgba(226,181,103,.35);border:1px solid rgba(226,181,103,.6);transform:translate(-50%,-50%)}
.touch-buttons{position:absolute;right:22px;bottom:104px;display:flex;gap:14px;align-items:flex-end;pointer-events:auto}
.touch-buttons button{
  width:76px;height:76px;border-radius:50%;background:rgba(5,8,12,.5);border:1px solid rgba(226,181,103,.42);
  color:var(--gold);font-size:9px;letter-spacing:.18em;backdrop-filter:blur(4px)
}
#touch-fire{width:92px;height:92px;border-color:rgba(255,61,80,.55);color:#ffb8bd;background:rgba(60,4,12,.38)}
#touch-dash{align-self:flex-start;margin-top:-54px;width:60px;height:60px;border-color:rgba(93,240,213,.5);color:var(--teal)}
@media (pointer:coarse){
  #touch-controls.touch-active{display:block}
  .ability-hints{display:none}
  .ammo-wrap{bottom:24px;right:20px;min-width:150px}
  .hud-left{width:170px}
  .depth-display{width:72vw}
  .hud-right{display:none}
  #reticle-hint{display:none}
}

/* ---------- responsive ---------- */
@media (max-width:900px){
  .screen{padding:32px 24px;align-items:center;background:radial-gradient(ellipse at 50% 40%,rgba(3,5,8,.62),rgba(3,5,8,.94))}
  .menu-frame{width:min(560px,100%);margin:auto;text-align:center}
  .eyebrow{justify-content:center}
  .title-rule{margin-left:auto;margin-right:auto}
  .tagline{margin-left:auto;margin-right:auto}
  .briefing{margin-left:auto;margin-right:auto}
  .controls-line{justify-content:center}
  .menu-footer{font-size:7px;letter-spacing:.15em;gap:10px;flex-wrap:wrap;justify-content:center;text-align:center}
  .menu-credit,.menu-sigil{display:none}
  .hunter-tag #stat-damage{display:none}
  .ability-hints{gap:11px}
  .ability-hints span:nth-child(n+3){display:none}
  #level-label{font-size:7px;letter-spacing:.2em}
}
@media (max-width:620px){
  .menu-frame h1{font-size:clamp(39px,12vw,62px)}
  .tagline{font-size:14px}
  .briefing div{padding:10px 6px;gap:7px;justify-content:center}
  .briefing span{font-size:7px;letter-spacing:.08em}
  .primary{min-width:190px;padding:14px 30px;font-size:10px}
  .controls-line{display:none}
  .hud-left{left:12px;top:12px;width:145px}
  .depth-display{top:8px;width:66vw}
  #floor-num{font-size:34px}
  .floor-pips i{width:11px}
  .hud-right{display:none}
  .ammo-wrap{right:12px;bottom:18px;min-width:140px}
  .weapon-name{font-size:7px}
  .ammo-pips i{width:6px;height:13px}
  .ability-hints{display:none}
  .panel{padding:28px 20px}
  .victory-stats b{font-size:21px}
}

// Procedural audio. No assets: every sound is synthesized with WebAudio.
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.ambient = null
    this.noise = null
    this.creakTimer = null
    this.muted = false
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    const comp = this.ctx.createDynamicsCompressor()
    comp.threshold.value = -18
    comp.knee.value = 22
    comp.ratio.value = 5
    comp.attack.value = 0.004
    comp.release.value = 0.22
    this.master = this.ctx.createGain()
    this.master.gain.value = 0.72
    this.master.connect(comp)
    comp.connect(this.ctx.destination)
    this.noise = this.makeNoise(2)
    this.startAmbient()
  }

  makeNoise(seconds = 1) {
    const rate = this.ctx.sampleRate
    const buffer = this.ctx.createBuffer(1, rate * seconds, rate)
    const data = buffer.getChannelData(0)
    let last = 0
    for (let i = 0; i < data.length; i++) {
      const white = Math.random() * 2 - 1
      last = (last + 0.04 * white) / 1.04
      data[i] = last * 2.6
    }
    return buffer
  }

  now() { return this.ctx ? this.ctx.currentTime : 0 }

  tone({ freq = 220, end = freq, dur = 0.2, type = 'sine', gain = 0.15, delay = 0, slide = 'exp' }) {
    if (!this.ctx) return
    const t = this.now() + delay
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(Math.max(20, freq), t)
    if (end !== freq) {
      if (slide === 'exp') osc.frequency.exponentialRampToValueAtTime(Math.max(20, end), t + dur)
      else osc.frequency.linearRampToValueAtTime(Math.max(20, end), t + dur)
    }
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + Math.min(0.012, dur * 0.2))
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    osc.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + dur + 0.03)
  }

  noiseBurst({ dur = 0.2, gain = 0.2, freq = 1200, q = 0.8, type = 'lowpass', delay = 0, sweep = null }) {
    if (!this.ctx) return
    const t = this.now() + delay
    const src = this.ctx.createBufferSource()
    src.buffer = this.noise
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.setValueAtTime(freq, t)
    filter.Q.value = q
    if (sweep) filter.frequency.exponentialRampToValueAtTime(Math.max(60, sweep), t + dur)
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.master)
    src.start(t, Math.random() * 0.5)
    src.stop(t + dur + 0.02)
  }

  startAmbient() {
    if (!this.ctx) return
    const t = this.now()
    const bus = this.ctx.createGain()
    bus.gain.value = 0
    bus.gain.linearRampToValueAtTime(0.11, t + 2.5)
    bus.connect(this.master)

    const drone = this.ctx.createOscillator()
    drone.type = 'sawtooth'
    drone.frequency.value = 42
    const droneFilter = this.ctx.createBiquadFilter()
    droneFilter.type = 'lowpass'
    droneFilter.frequency.value = 120
    droneFilter.Q.value = 3
    const droneGain = this.ctx.createGain()
    droneGain.gain.value = 0.22
    drone.connect(droneFilter)
    droneFilter.connect(droneGain)
    droneGain.connect(bus)
    drone.start(t)

    const fifth = this.ctx.createOscillator()
    fifth.type = 'sine'
    fifth.frequency.value = 63.5
    const fifthGain = this.ctx.createGain()
    fifthGain.gain.value = 0.1
    fifth.connect(fifthGain)
    fifthGain.connect(bus)
    fifth.start(t)

    const wind = this.ctx.createBufferSource()
    wind.buffer = this.noise
    wind.loop = true
    const windFilter = this.ctx.createBiquadFilter()
    windFilter.type = 'bandpass'
    windFilter.frequency.value = 240
    windFilter.Q.value = 0.6
    const windGain = this.ctx.createGain()
    windGain.gain.value = 0.16
    wind.connect(windFilter)
    windFilter.connect(windGain)
    windGain.connect(bus)
    wind.start(t)

    const lfo = this.ctx.createOscillator()
    lfo.type = 'sine'
    lfo.frequency.value = 0.06
    const lfoGain = this.ctx.createGain()
    lfoGain.gain.value = 38
    lfo.connect(lfoGain)
    lfoGain.connect(droneFilter.frequency)
    lfo.start(t)

    this.ambient = { bus, drone, fifth, wind, lfo }
    this.scheduleCreak()
  }

  scheduleCreak() {
    if (!this.ctx) return
    clearTimeout(this.creakTimer)
    const delay = 5000 + Math.random() * 9000
    this.creakTimer = setTimeout(() => {
      if (!this.ctx) return
      this.noiseBurst({ dur: 0.9, gain: 0.035, freq: 700 + Math.random() * 700, q: 9, type: 'bandpass', sweep: 220 })
      this.tone({ freq: 90 + Math.random() * 30, end: 55, dur: 1.4, type: 'triangle', gain: 0.025 })
      this.scheduleCreak()
    }, delay)
  }

  setDepth(intensity = 0) {
    if (!this.ambient || !this.ctx) return
    this.ambient.wind.playbackRate.value = 1 + intensity * 0.7
    this.ambient.bus.gain.setTargetAtTime(0.11 + intensity * 0.07, this.now(), 0.3)
  }

  shot() {
    this.noiseBurst({ dur: 0.14, gain: 0.34, freq: 5200, q: 1.1, type: 'highpass', sweep: 900 })
    this.tone({ freq: 150, end: 44, dur: 0.22, type: 'sawtooth', gain: 0.22 })
    this.tone({ freq: 880, end: 160, dur: 0.1, type: 'square', gain: 0.055 })
  }
  empty() { this.tone({ freq: 260, end: 180, dur: 0.05, type: 'square', gain: 0.05 }) }
  reload() {
    this.noiseBurst({ dur: 0.05, gain: 0.1, freq: 2600, q: 2, type: 'bandpass' })
    this.tone({ freq: 340, end: 220, dur: 0.06, type: 'square', gain: 0.04, delay: 0.28 })
    this.noiseBurst({ dur: 0.07, gain: 0.12, freq: 1800, q: 2, type: 'bandpass', delay: 0.48 })
    this.tone({ freq: 620, end: 420, dur: 0.08, type: 'triangle', gain: 0.045, delay: 0.72 })
  }
  hit(head = false) {
    if (head) {
      this.tone({ freq: 1250, end: 820, dur: 0.09, type: 'triangle', gain: 0.14 })
      this.noiseBurst({ dur: 0.06, gain: 0.12, freq: 3800, q: 2, type: 'bandpass' })
    } else {
      this.tone({ freq: 520, end: 340, dur: 0.05, type: 'square', gain: 0.06 })
      this.noiseBurst({ dur: 0.045, gain: 0.09, freq: 2200, q: 1.5, type: 'bandpass' })
    }
  }
  kill() {
    this.tone({ freq: 180, end: 42, dur: 0.5, type: 'sawtooth', gain: 0.13 })
    this.noiseBurst({ dur: 0.45, gain: 0.12, freq: 1100, q: 0.7, sweep: 180 })
  }
  hurt() {
    this.tone({ freq: 120, end: 38, dur: 0.35, type: 'sawtooth', gain: 0.22 })
    this.noiseBurst({ dur: 0.25, gain: 0.2, freq: 900, q: 0.6, sweep: 120 })
  }
  dash() {
    this.noiseBurst({ dur: 0.26, gain: 0.18, freq: 600, q: 0.7, type: 'bandpass', sweep: 3200 })
    this.tone({ freq: 320, end: 700, dur: 0.18, type: 'sine', gain: 0.045 })
  }
  pickup() {
    this.tone({ freq: 620, end: 880, dur: 0.12, type: 'sine', gain: 0.1 })
    this.tone({ freq: 930, end: 1240, dur: 0.16, type: 'sine', gain: 0.07, delay: 0.08 })
  }
  chime() {
    this.tone({ freq: 523.25, dur: 0.8, type: 'sine', gain: 0.12 })
    this.tone({ freq: 659.25, dur: 1.0, type: 'sine', gain: 0.08, delay: 0.12 })
    this.tone({ freq: 783.99, dur: 1.3, type: 'sine', gain: 0.06, delay: 0.26 })
  }
  bossRoar() {
    this.tone({ freq: 58, end: 31, dur: 2.2, type: 'sawtooth', gain: 0.3 })
    this.tone({ freq: 92, end: 44, dur: 1.8, type: 'square', gain: 0.11, delay: 0.08 })
    this.noiseBurst({ dur: 2.1, gain: 0.2, freq: 700, q: 0.5, sweep: 90 })
  }
  bossSlam() {
    this.tone({ freq: 82, end: 24, dur: 0.8, type: 'sawtooth', gain: 0.32 })
    this.noiseBurst({ dur: 0.7, gain: 0.3, freq: 500, q: 0.4, sweep: 60 })
  }
  spit() {
    this.tone({ freq: 210, end: 95, dur: 0.25, type: 'sawtooth', gain: 0.07 })
    this.noiseBurst({ dur: 0.22, gain: 0.08, freq: 800, q: 3, sweep: 280 })
  }
  descend(stop = false) {
    if (stop) {
      this.noiseBurst({ dur: 0.22, gain: 0.16, freq: 600, q: 0.6, type: 'lowpass', sweep: 90 })
      this.tone({ freq: 68, end: 42, dur: 0.5, type: 'sine', gain: 0.2 })
      return
    }
    this.noiseBurst({ dur: 1.9, gain: 0.13, freq: 320, q: 0.5, type: 'lowpass', sweep: 80 })
    this.tone({ freq: 55, end: 36, dur: 1.9, type: 'sawtooth', gain: 0.1 })
  }
  banish() {
    this.tone({ freq: 146.8, dur: 3.2, type: 'sine', gain: 0.18 })
    this.tone({ freq: 220, dur: 3.0, type: 'sine', gain: 0.12, delay: 0.28 })
    this.tone({ freq: 293.6, dur: 2.8, type: 'sine', gain: 0.1, delay: 0.56 })
    this.tone({ freq: 440, dur: 2.6, type: 'sine', gain: 0.08, delay: 0.9 })
    this.noiseBurst({ dur: 2.8, gain: 0.14, freq: 500, q: 0.8, type: 'bandpass', sweep: 4200 })
  }
  victory() {
    const notes = [261.6, 329.6, 392, 523.3, 659.3]
    notes.forEach((f, i) => this.tone({ freq: f, dur: 1.6 + i * 0.2, type: 'sine', gain: 0.09, delay: i * 0.22 }))
  }
  click() { this.tone({ freq: 880, end: 520, dur: 0.05, type: 'square', gain: 0.04 }) }
}

export const audio = new AudioEngine()

import * as THREE from 'three'

function canvas(width, height) {
  const c = document.createElement('canvas')
  c.width = width
  c.height = height
  return c
}

function grain(ctx, w, h, amount = 1200, alpha = 0.16) {
  for (let i = 0; i < amount; i++) {
    const v = Math.random() * 255 | 0
    ctx.fillStyle = `rgba(${v},${v},${v},${Math.random() * alpha})`
    ctx.fillRect(Math.random() * w, Math.random() * h, 1 + Math.random() * 2, 1 + Math.random() * 2)
  }
}

function rivet(ctx, x, y, r = 3) {
  ctx.fillStyle = '#050608'
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill()
  ctx.fillStyle = 'rgba(255,235,200,.14)'
  ctx.beginPath(); ctx.arc(x - r * 0.3, y - r * 0.3, r * 0.55, 0, Math.PI * 2); ctx.fill()
}

export function makeFloorTexture(accent = '#e2b567') {
  const w = 1024, h = 1024
  const c = canvas(w, h)
  const ctx = c.getContext('2d')
  const cx = w / 2, cy = h / 2

  ctx.fillStyle = '#0b0e12'
  ctx.fillRect(0, 0, w, h)

  // radial deck plates
  const wedges = 16
  for (let i = 0; i < wedges; i++) {
    const a0 = (i / wedges) * Math.PI * 2
    const a1 = ((i + 1) / wedges) * Math.PI * 2
    const tone = 18 + (i % 3) * 5 + (i % 2) * 4
    ctx.beginPath()
    ctx.moveTo(cx, cy)
    ctx.arc(cx, cy, 500, a0, a1)
    ctx.closePath()
    ctx.fillStyle = `rgb(${tone},${tone + 2},${tone + 5})`
    ctx.fill()
    ctx.strokeStyle = 'rgba(0,0,0,.6)'
    ctx.lineWidth = 3
    ctx.stroke()
  }

  // concentric grooves
  for (const r of [128, 240, 358, 470]) {
    ctx.strokeStyle = 'rgba(0,0,0,.65)'
    ctx.lineWidth = 7
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke()
    ctx.strokeStyle = 'rgba(255,240,210,.055)'
    ctx.lineWidth = 2
    ctx.beginPath(); ctx.arc(cx, cy, r + 5, 0, Math.PI * 2); ctx.stroke()
  }

  // radial seams + rivets
  for (let i = 0; i < wedges; i++) {
    const a = (i / wedges) * Math.PI * 2
    ctx.strokeStyle = 'rgba(0,0,0,.55)'
    ctx.lineWidth = 5
    ctx.beginPath()
    ctx.moveTo(cx + Math.cos(a) * 90, cy + Math.sin(a) * 90)
    ctx.lineTo(cx + Math.cos(a) * 500, cy + Math.sin(a) * 500)
    ctx.stroke()
    for (let r = 165; r < 500; r += 72) {
      rivet(ctx, cx + Math.cos(a + 0.05) * r, cy + Math.sin(a + 0.05) * r, 2.6)
    }
  }

  // central occult sigil
  ctx.save()
  ctx.translate(cx, cy)
  const aura = ctx.createRadialGradient(0, 0, 20, 0, 0, 220)
  aura.addColorStop(0, 'rgba(255,255,255,.06)')
  aura.addColorStop(1, 'rgba(0,0,0,0)')
  ctx.fillStyle = aura
  ctx.beginPath(); ctx.arc(0, 0, 220, 0, Math.PI * 2); ctx.fill()
  ctx.strokeStyle = accent
  ctx.globalAlpha = 0.55
  ctx.lineWidth = 3
  ctx.beginPath(); ctx.arc(0, 0, 176, 0, Math.PI * 2); ctx.stroke()
  ctx.beginPath(); ctx.arc(0, 0, 142, 0, Math.PI * 2); ctx.stroke()
  ctx.lineWidth = 2.5
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2
    ctx.beginPath()
    ctx.moveTo(Math.cos(a) * 142, Math.sin(a) * 142)
    ctx.lineTo(Math.cos(a) * 176, Math.sin(a) * 176)
    ctx.stroke()
  }
  ctx.beginPath()
  for (let i = 0; i < 5; i++) {
    const a = -Math.PI / 2 + (i * 4 * Math.PI) / 5
    const x = Math.cos(a) * 118, y = Math.sin(a) * 118
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y)
  }
  ctx.closePath()
  ctx.stroke()
  ctx.globalAlpha = 0.95
  ctx.fillStyle = accent
  ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill()
  ctx.restore()

  // hazard band at edge
  ctx.save()
  ctx.translate(cx, cy)
  ctx.rotate(-0.35)
  ctx.globalAlpha = 0.34
  ctx.fillStyle = '#e2b567'
  for (let x = -720; x < 720; x += 56) {
    ctx.beginPath()
    ctx.rect(x, 476, 22, 34)
    ctx.fill()
  }
  ctx.restore()

  // scratches and grime
  for (let i = 0; i < 90; i++) {
    ctx.strokeStyle = `rgba(255,235,205,${Math.random() * 0.045})`
    ctx.lineWidth = Math.random() * 1.6
    const x = Math.random() * w, y = Math.random() * h
    ctx.beginPath()
    ctx.moveTo(x, y)
    ctx.lineTo(x + (Math.random() - 0.5) * 90, y + (Math.random() - 0.5) * 90)
    ctx.stroke()
  }
  grain(ctx, w, h, 2500, 0.11)

  const texture = new THREE.CanvasTexture(c)
  texture.colorSpace = THREE.SRGBColorSpace
  texture.anisotropy = 8
  return texture
}

export function makeWallTexture() {
  const w = 512, h = 1024
  const c = canvas(w, h)
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#11151a'
  ctx.fillRect(0, 0, w, h)

  // large plates
  for (let row = 0; row < 4; row++) {
    const y = row * 256
    ctx.fillStyle = row % 2 ? 'rgba(255,255,255,.018)' : 'rgba(0,0,0,.1)'
    ctx.fillRect(0, y, w, 256)
    ctx.strokeStyle = 'rgba(0,0,0,.7)'
    ctx.lineWidth = 8
    ctx.strokeRect(-4, y, w + 8, 256)
    ctx.strokeStyle = 'rgba(255,240,210,.04)'
    ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(0, y + 8); ctx.lineTo(w, y + 8); ctx.stroke()
    for (let x = 12; x < w; x += 46) {
      rivet(ctx, x, y + 18, 3)
      rivet(ctx, x, y + 238, 3)
    }
  }

  // vertical seams
  for (let x = 0; x < w; x += 128) {
    ctx.strokeStyle = 'rgba(0,0,0,.55)'
    ctx.lineWidth = 9
    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke()
    ctx.strokeStyle = 'rgba(255,240,210,.045)'
    ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(x + 6, 0); ctx.lineTo(x + 6, h); ctx.stroke()
  }

  // rust / damp streaks
  for (let i = 0; i < 80; i++) {
    const x = Math.random() * w
    const y = Math.random() * h
    const len = 40 + Math.random() * 240
    const g = ctx.createLinearGradient(x, y, x, y + len)
    const warm = 60 + Math.random() * 30
    g.addColorStop(0, `rgba(${warm + 30},${warm * 0.55},${warm * 0.25},${Math.random() * 0.14})`)
    g.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = g
    ctx.fillRect(x, y, 1 + Math.random() * 8, len)
  }

  // diagonal grime
  ctx.globalAlpha = 0.12
  ctx.strokeStyle = '#000'
  for (let i = 0; i < 28; i++) {
    ctx.lineWidth = 4 + Math.random() * 16
    ctx.beginPath()
    ctx.moveTo(-50, Math.random() * h)
    ctx.lineTo(w + 50, Math.random() * h)
    ctx.stroke()
  }
  ctx.globalAlpha = 1
  grain(ctx, w, h, 1800, 0.13)

  const texture = new THREE.CanvasTexture(c)
  texture.colorSpace = THREE.SRGBColorSpace
  texture.wrapS = THREE.RepeatWrapping
  texture.wrapT = THREE.RepeatWrapping
  texture.repeat.set(6, 8)
  texture.anisotropy = 8
  return texture
}

export function makeSign() {
  const w = 1024, h = 512
  const c = canvas(w, h)
  const ctx = c.getContext('2d')
  const texture = new THREE.CanvasTexture(c)
  texture.colorSpace = THREE.SRGBColorSpace
  texture.anisotropy = 8

  function update({ levelRoman = 'I', floor = 1, name = 'THE RUSTED FOUNDRY', accent = '#e2b567', boss = false }) {
    ctx.clearRect(0, 0, w, h)
    ctx.fillStyle = 'rgba(3,5,8,.92)'
    ctx.fillRect(0, 0, w, h)

    const glow = ctx.createRadialGradient(w / 2, h / 2, 30, w / 2, h / 2, 430)
    glow.addColorStop(0, boss ? 'rgba(255,40,60,.16)' : 'rgba(226,181,103,.12)')
    glow.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = glow
    ctx.fillRect(0, 0, w, h)

    ctx.strokeStyle = accent
    ctx.globalAlpha = 0.48
    ctx.lineWidth = 3
    ctx.strokeRect(22, 22, w - 44, h - 44)
    ctx.globalAlpha = 0.2
    ctx.strokeRect(36, 36, w - 72, h - 72)
    ctx.globalAlpha = 1

    // corner ticks
    ctx.strokeStyle = accent
    ctx.lineWidth = 5
    for (const [x, y, dx, dy] of [[22, 22, 1, 1], [w - 22, 22, -1, 1], [22, h - 22, 1, -1], [w - 22, h - 22, -1, -1]]) {
      ctx.beginPath(); ctx.moveTo(x, y + dy * 42); ctx.lineTo(x, y); ctx.lineTo(x + dx * 42, y); ctx.stroke()
    }

    ctx.textAlign = 'center'
    ctx.fillStyle = accent
    ctx.font = '600 27px ui-monospace, Menlo, Consolas, monospace'
    ctx.letterSpacing = '13px'
    ctx.fillText(`STRATUM ${levelRoman}`, w / 2, 108)
    ctx.letterSpacing = '0px'

    ctx.fillStyle = '#f0eadb'
    ctx.font = '400 168px Georgia, serif'
    ctx.fillText(`-${String(floor).padStart(2, '0')}`, w / 2, 288)

    ctx.fillStyle = boss ? '#ff596e' : accent
    ctx.globalAlpha = 0.85
    ctx.font = '600 26px ui-monospace, Menlo, Consolas, monospace'
    ctx.letterSpacing = '10px'
    ctx.fillText(name, w / 2, 358)
    ctx.letterSpacing = '0px'
    ctx.globalAlpha = 1

    // floor pips
    const pipW = 58, gap = 12, total = 10 * pipW + 9 * gap
    let x = (w - total) / 2
    for (let i = 0; i < 10; i++) {
      ctx.fillStyle = i < floor ? accent : 'rgba(255,255,255,.12)'
      ctx.globalAlpha = i + 1 === floor ? 1 : 0.7
      ctx.fillRect(x, 410, pipW, 6)
      x += pipW + gap
    }
    ctx.globalAlpha = 1

    ctx.fillStyle = 'rgba(233,227,211,.4)'
    ctx.font = '500 17px ui-monospace, Menlo, Consolas, monospace'
    ctx.letterSpacing = '8px'
    ctx.fillText(boss ? 'THE WARDEN WAITS' : 'DESCEND TO PURGE', w / 2, 462)
    ctx.letterSpacing = '0px'

    texture.needsUpdate = true
  }

  return { texture, update }
}

export function makeGlowTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)') {
  const size = 128
  const c = canvas(size, size)
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  g.addColorStop(0, inner)
  g.addColorStop(0.32, inner.replace(/[\d.]+\)$/, '0.55)'))
  g.addColorStop(1, outer)
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

export function makeSigilTexture(accent = '#ff3d50') {
  const size = 512
  const c = canvas(size, size)
  const ctx = c.getContext('2d')
  const cx = size / 2, cy = size / 2
  ctx.translate(cx, cy)
  ctx.strokeStyle = accent
  ctx.globalAlpha = 1
  ctx.lineWidth = 4
  for (const r of [230, 188, 154]) {
    ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke()
  }
  ctx.lineWidth = 3
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2
    ctx.beginPath()
    ctx.moveTo(Math.cos(a) * 154, Math.sin(a) * 154)
    ctx.lineTo(Math.cos(a) * 188, Math.sin(a) * 188)
    ctx.stroke()
  }
  ctx.beginPath()
  for (let i = 0; i < 7; i++) {
    const a = -Math.PI / 2 + (i * 6 * Math.PI) / 7
    const x = Math.cos(a) * 140, y = Math.sin(a) * 140
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y)
  }
  ctx.closePath()
  ctx.stroke()
  ctx.globalAlpha = 0.5
  ctx.lineWidth = 2
  for (let i = 0; i < 28; i++) {
    const a = (i / 28) * Math.PI * 2
    ctx.beginPath()
    ctx.moveTo(Math.cos(a) * 195, Math.sin(a) * 195)
    ctx.lineTo(Math.cos(a) * 226, Math.sin(a) * 226)
    ctx.stroke()
  }
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

import * as THREE from 'three'
import { makeFloorTexture, makeWallTexture, makeSign, makeGlowTexture, makeSigilTexture } from './textures.js'

export const THEMES = [
  {
    key: 'foundry',
    name: 'THE RUSTED FOUNDRY',
    roman: 'I',
    accent: 0xe2b567,
    accentCss: '#e2b567',
    fog: 0x090705,
    wall: 0x16120e,
    key: 0xffbe78,
    rim: 0xff7426,
    rail: 0xff9a4d,
    bg: 0x030302
  },
  {
    key: 'reliquary',
    name: 'THE DROWNED RELIQUARY',
    roman: 'II',
    accent: 0x4ce3cb,
    accentCss: '#4ce3cb',
    fog: 0x031012,
    wall: 0x0a1718,
    key: 0x9eeaff,
    rim: 0x18d3bd,
    rail: 0x4ce3cb,
    bg: 0x020607
  },
  {
    key: 'chasm',
    name: 'THE BLOOD CHASM',
    roman: 'III',
    accent: 0xff4058,
    accentCss: '#ff4058',
    fog: 0x120306,
    wall: 0x190609,
    key: 0xffc0ac,
    rim: 0xff1e3c,
    rail: 0xff4058,
    bg: 0x060102
  }
]

export function createWorld(scene, renderer) {
  const world = {
    group: new THREE.Group(),
    themeIndex: 0,
    descent: false,
    descentSpeed: 0,
    time: 0,
    sign: makeSign(),
    lampLights: [],
    railLights: [],
    rings: null,
    wallTexture: null,
    bossSigil: null,
    bossBraziers: [],
    dust: null
  }
  scene.add(world.group)

  scene.background = new THREE.Color(0x030302)
  scene.fog = new THREE.FogExp2(0x090705, 0.023)

  // ---------- lighting ----------
  const hemi = new THREE.HemisphereLight(0x51687f, 0x0a0806, 0.55)
  scene.add(hemi)
  world.hemi = hemi

  const key = new THREE.SpotLight(0xffbe78, 110, 60, Math.PI * 0.34, 0.55, 1.15)
  key.position.set(0, 19, 3)
  key.target.position.set(0, 0, 0)
  key.castShadow = true
  key.shadow.mapSize.set(1024, 1024)
  key.shadow.camera.near = 2
  key.shadow.camera.far = 42
  key.shadow.bias = -0.0007
  key.shadow.radius = 3
  scene.add(key, key.target)
  world.key = key

  const rim = new THREE.PointLight(0xff7426, 45, 34, 1.7)
  rim.position.set(-12, 8, -12)
  scene.add(rim)
  world.rim = rim

  const rim2 = new THREE.PointLight(0xff7426, 30, 30, 1.7)
  rim2.position.set(12, 5, 11)
  scene.add(rim2)
  world.rim2 = rim2

  // ---------- shaft ----------
  const shaft = new THREE.Group()
  world.group.add(shaft)
  world.shaft = shaft

  const wallTexture = makeWallTexture()
  world.wallTexture = wallTexture
  const wallMat = new THREE.MeshStandardMaterial({
    map: wallTexture,
    color: 0x16120e,
    metalness: 0.72,
    roughness: 0.58
  })
  world.wallMat = wallMat
  const wall = new THREE.Mesh(new THREE.CylinderGeometry(24, 24, 190, 64, 1, true), wallMat)
  wall.position.y = 32
  shaft.add(wall)

  // vertical structural ribs
  const ribMat = new THREE.MeshStandardMaterial({ color: 0x0a0c0f, metalness: 0.9, roughness: 0.42 })
  world.ribMat = ribMat
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2
    const rib = new THREE.Mesh(new THREE.BoxGeometry(0.64, 190, 0.9), ribMat)
    rib.position.set(Math.sin(a) * 23.4, 32, Math.cos(a) * 23.4)
    rib.rotation.y = a
    shaft.add(rib)
  }

  // rings scrolling past to sell the descent
  const ringGroup = new THREE.Group()
  shaft.add(ringGroup)
  world.rings = ringGroup
  const ringMat = new THREE.MeshStandardMaterial({
    color: 0x2b2116,
    emissive: 0xff7426,
    emissiveIntensity: 1.4,
    metalness: 0.7,
    roughness: 0.35
  })
  world.ringMat = ringMat
  const ringGeo = new THREE.TorusGeometry(23.25, 0.16, 6, 72)
  for (let i = 0; i < 16; i++) {
    const ring = new THREE.Mesh(ringGeo, ringMat)
    ring.rotation.x = Math.PI / 2
    ring.position.y = i * 14 - 66
    ringGroup.add(ring)
    // lamps inset around every other ring
    if (i % 2 === 0) {
      for (let j = 0; j < 8; j++) {
        const a = (j / 8) * Math.PI * 2 + (i % 4) * 0.15
        const panel = new THREE.Mesh(
          new THREE.BoxGeometry(1.8, 0.34, 0.18),
          new THREE.MeshBasicMaterial({ color: 0xff9a4d })
        )
        panel.position.set(Math.sin(a) * 22.9, i * 14 - 66, Math.cos(a) * 22.9)
        panel.rotation.y = a
        ringGroup.add(panel)
        if (j === 0) world.railLights.push(panel)
      }
    }
  }

  // cables
  const cableMat = new THREE.MeshStandardMaterial({ color: 0x1c1f24, metalness: 0.95, roughness: 0.34 })
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2 + Math.PI / 4
    const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.085, 132, 6), cableMat)
    cable.position.set(Math.sin(a) * 6.4, 72, Math.cos(a) * 6.4)
    shaft.add(cable)
  }

  // ---------- hanging floor signs ----------
  const signMat = new THREE.MeshBasicMaterial({ map: world.sign.texture, transparent: true, side: THREE.DoubleSide, toneMapped: false })
  world.signMat = signMat
  const frameMat = new THREE.MeshStandardMaterial({ color: 0x080a0d, metalness: 0.8, roughness: 0.5 })
  for (const [z, rot] of [[19.85, Math.PI], [-19.85, 0]]) {
    const frame = new THREE.Mesh(new THREE.BoxGeometry(9.6, 5.1, 0.28), frameMat)
    frame.position.set(0, 8.2, z + (z > 0 ? 0.14 : -0.14))
    frame.rotation.y = rot
    shaft.add(frame)
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(9.1, 4.55), signMat)
    sign.position.set(0, 8.2, z)
    sign.rotation.y = rot
    shaft.add(sign)
    // overhead spotlight bar
    for (let i = -1; i <= 1; i++) {
      const bolt = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.6, 6), frameMat)
      bolt.rotation.x = Math.PI / 2
      bolt.position.set(i * 3.7, 10.85, z)
      shaft.add(bolt)
    }
  }

  // ---------- platform ----------
  const platform = new THREE.Group()
  world.group.add(platform)
  world.platform = platform

  const baseMat = new THREE.MeshStandardMaterial({ color: 0x11151a, metalness: 0.85, roughness: 0.42 })
  const base = new THREE.Mesh(new THREE.CylinderGeometry(10.2, 9.65, 0.92, 48), baseMat)
  base.position.y = -0.46
  base.receiveShadow = true
  base.castShadow = true
  platform.add(base)

  const floorTex = makeFloorTexture('#e2b567')
  world.floorTex = floorTex
  const floorMat = new THREE.MeshStandardMaterial({ map: floorTex, color: 0xffffff, metalness: 0.62, roughness: 0.55 })
  world.floorMat = floorMat
  const floor = new THREE.Mesh(new THREE.CircleGeometry(10.07, 64), floorMat)
  floor.rotation.x = -Math.PI / 2
  floor.receiveShadow = true
  platform.add(floor)

  // rim
  const rimMat = new THREE.MeshStandardMaterial({ color: 0x2a2015, metalness: 0.9, roughness: 0.35, emissive: 0xff7426, emissiveIntensity: 0.12 })
  world.platformRimMat = rimMat
  const platformRim = new THREE.Mesh(new THREE.TorusGeometry(10.02, 0.2, 8, 72), rimMat)
  platformRim.rotation.x = Math.PI / 2
  platformRim.position.y = 0.02
  platform.add(platformRim)

  // under-glow
  const glowMat = new THREE.MeshBasicMaterial({ color: 0xff7426 })
  world.glowMat = glowMat
  const underGlow = new THREE.Mesh(new THREE.TorusGeometry(9.45, 0.07, 6, 72), glowMat)
  underGlow.rotation.x = Math.PI / 2
  underGlow.position.y = -0.96
  platform.add(underGlow)

  // below-deck machinery
  const engineMat = new THREE.MeshStandardMaterial({ color: 0x0a0d11, metalness: 0.9, roughness: 0.5 })
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2
    const fin = new THREE.Mesh(new THREE.BoxGeometry(0.28, 1.6, 2.5), engineMat)
    fin.position.set(Math.sin(a) * 5.4, -1.65, Math.cos(a) * 5.4)
    fin.rotation.y = a
    platform.add(fin)
  }
  const engine = new THREE.Mesh(new THREE.CylinderGeometry(3.9, 2.7, 3.1, 16), engineMat)
  engine.position.y = -2.9
  platform.add(engine)
  const engineCore = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 1.2, 3.3, 16), new THREE.MeshBasicMaterial({ color: 0xff7a2e }))
  engineCore.position.y = -2.9
  platform.add(engineCore)
  world.engineCore = engineCore

  // railing
  const railMat = new THREE.MeshStandardMaterial({ color: 0x262b31, metalness: 0.9, roughness: 0.35 })
  const postGeo = new THREE.BoxGeometry(0.065, 1.22, 0.065)
  world.railLightMats = []
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2
    const post = new THREE.Mesh(postGeo, railMat)
    post.position.set(Math.sin(a) * 9.86, 0.62, Math.cos(a) * 9.86)
    platform.add(post)
    if (i % 3 === 0) {
      const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.055, 6, 6), new THREE.MeshBasicMaterial({ color: 0xff9a4d }))
      bulb.position.set(Math.sin(a) * 9.86, 1.24, Math.cos(a) * 9.86)
      platform.add(bulb)
      world.railLightMats.push(bulb.material)
    }
  }
  const railRingMat = new THREE.MeshStandardMaterial({ color: 0x31363c, metalness: 0.95, roughness: 0.3 })
  for (const y of [0.58, 1.18]) {
    const bar = new THREE.Mesh(new THREE.TorusGeometry(9.86, 0.045, 5, 96), railRingMat)
    bar.rotation.x = Math.PI / 2
    bar.position.y = y
    platform.add(bar)
  }

  // overhead cage
  const cage = new THREE.Group()
  platform.add(cage)
  const topRing = new THREE.Mesh(new THREE.TorusGeometry(8.6, 0.11, 6, 64), railMat)
  topRing.rotation.x = Math.PI / 2
  topRing.position.y = 8.6
  cage.add(topRing)
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2 + Math.PI / 8
    const beam = new THREE.Mesh(new THREE.BoxGeometry(0.16, 8.6, 0.16), railMat)
    beam.position.set(Math.sin(a) * 8.55, 4.3, Math.cos(a) * 8.55)
    beam.rotation.y = a
    cage.add(beam)
    const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 8.5, 4), new THREE.MeshBasicMaterial({ color: 0x36322a }))
    cable.position.set(Math.sin(a) * 8.55, 4.3, Math.cos(a) * 8.55)
    cage.add(cable)
  }
  // hanging lamps
  const lampMat = new THREE.MeshStandardMaterial({ color: 0x2b1c0d, emissive: 0xff9a4d, emissiveIntensity: 2.2, metalness: 0.6, roughness: 0.4 })
  world.lampMat = lampMat
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2 + Math.PI / 4
    const x = Math.sin(a) * 6.2, z = Math.cos(a) * 6.2
    const chain = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 2.4, 4), railMat)
    chain.position.set(x, 7.4, z)
    cage.add(chain)
    const shade = new THREE.Mesh(new THREE.ConeGeometry(0.55, 0.75, 10, 1, true), new THREE.MeshStandardMaterial({ color: 0x171a1e, metalness: 0.85, roughness: 0.4, side: THREE.DoubleSide }))
    shade.position.set(x, 6.15, z)
    cage.add(shade)
    const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 8), lampMat)
    bulb.position.set(x, 5.88, z)
    cage.add(bulb)
    const light = new THREE.PointLight(0xff9a4d, 11, 14, 1.8)
    light.position.set(x, 5.8, z)
    cage.add(light)
    world.lampLights.push(light)
  }

  // ---------- boss floor dressing ----------
  const sigilMat = new THREE.MeshBasicMaterial({
    map: makeSigilTexture('#ff4058'),
    transparent: true,
    opacity: 0.7,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide
  })
  world.bossSigil = new THREE.Mesh(new THREE.PlaneGeometry(15, 15), sigilMat)
  world.bossSigil.rotation.x = -Math.PI / 2
  world.bossSigil.position.y = 0.012
  world.bossSigil.visible = false
  platform.add(world.bossSigil)

  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2 + Math.PI / 4
    const brazier = new THREE.Group()
    brazier.position.set(Math.sin(a) * 8.9, 0, Math.cos(a) * 8.9)
    const bowl = new THREE.Mesh(
      new THREE.CylinderGeometry(0.55, 0.28, 0.45, 10, 1, true),
      new THREE.MeshStandardMaterial({ color: 0x1b1210, metalness: 0.8, roughness: 0.45, side: THREE.DoubleSide })
    )
    bowl.position.y = 0.8
    brazier.add(bowl)
    const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.13, 0.8, 6), new THREE.MeshStandardMaterial({ color: 0x211714, metalness: 0.85, roughness: 0.4 }))
    stem.position.y = 0.4
    brazier.add(stem)
    const flame = new THREE.Mesh(new THREE.ConeGeometry(0.3, 0.9, 8), new THREE.MeshBasicMaterial({ color: 0xff5a3c, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false }))
    flame.position.y = 1.42
    brazier.add(flame)
    const light = new THREE.PointLight(0xff3a2a, 13, 13, 1.8)
    light.position.y = 1.6
    brazier.add(light)
    brazier.visible = false
    platform.add(brazier)
    world.bossBraziers.push({ group: brazier, flame, light, phase: Math.random() * 6 })
  }

  // ---------- dust / embers ----------
  const dustCount = 360
  const dustGeo = new THREE.BufferGeometry()
  const positions = new Float32Array(dustCount * 3)
  const speeds = new Float32Array(dustCount)
  for (let i = 0; i < dustCount; i++) {
    const r = 6 + Math.random() * 16
    const a = Math.random() * Math.PI * 2
    positions[i * 3] = Math.sin(a) * r
    positions[i * 3 + 1] = Math.random() * 34 - 2
    positions[i * 3 + 2] = Math.cos(a) * r
    speeds[i] = 0.12 + Math.random() * 0.5
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  const dustMat = new THREE.PointsMaterial({
    color: 0xffd2a0,
    size: 0.055,
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
    blending: THREE.AdditiveBlending
  })
  const dust = new THREE.Points(dustGeo, dustMat)
  scene.add(dust)
  world.dust = dust
  world.dustSpeed = speeds
  world.dustMat = dustMat

  // glow sprite pool is managed by FX; keep a reusable radial texture
  world.glowTexture = makeGlowTexture()

  // ---------- theme ----------
  world.setTheme = (index) => {
    index = Math.max(0, Math.min(THEMES.length - 1, index))
    world.themeIndex = index
    const t = THEMES[index]
    scene.fog.color.setHex(t.fog)
    scene.background.setHex(t.bg)
    world.hemi.color.setHex(t.key)
    world.hemi.groundColor.setHex(t.fog)
    world.key.color.setHex(t.key)
    world.rim.color.setHex(t.rim)
    world.rim2.color.setHex(t.rim)
    world.wallMat.color.setHex(t.wall)
    world.ringMat.emissive.setHex(t.rail)
    world.ringMat.color.setHex(t.rail)
    world.floorMat.emissive = world.floorMat.emissive || new THREE.Color()
    world.floorMat.emissive.setHex(t.rail)
    world.floorMat.emissiveIntensity = 0.035
    world.platformRimMat.emissive.setHex(t.rail)
    world.glowMat.color.setHex(t.rail)
    world.lampMat.emissive.setHex(t.key)
    world.engineCore.material.color.setHex(t.rim)
    world.railLightMats.forEach(m => m.color.setHex(t.rail))
    world.railLights.forEach(m => m.material.color.setHex(t.rail))
    world.lampLights.forEach(l => l.color.setHex(t.key))
    world.dustMat.color.setHex(t.accent)
    world.bossSigil.material.color.setHex(t.accent)
    document.documentElement.style.setProperty('--gold', t.accentCss)
    document.documentElement.style.setProperty('--gold-hot', t.accentCss)
  }
  world.setTheme(0)

  world.setSign = ({ levelRoman, floor, name, accent, boss }) => {
    world.sign.update({ levelRoman, floor, name, accent, boss })
    world.signMat.map.needsUpdate = true
  }
  world.setSign({ levelRoman: 'I', floor: 1, name: THEMES[0].name, accent: THEMES[0].accentCss })
  world.signMat.map.needsUpdate = true

  world.setBossArea = (on) => {
    world.bossSigil.visible = on
    world.bossBraziers.forEach(b => { b.group.visible = on })
  }

  world.setDescent = (on) => {
    world.descent = on
    document.getElementById('descent-streaks')?.classList.toggle('on', on)
  }

  world.update = (dt, t) => {
    world.time = t
    if (world.descent) {
      ringGroup.position.y += dt * 7.2
      if (ringGroup.position.y > 14) ringGroup.position.y -= 14
      if (world.wallTexture) world.wallTexture.offset.y = (world.wallTexture.offset.y + dt * 0.16) % 1
      world.dust.position.y = (world.dust.position.y + dt * 5.5) % 14
    } else {
      world.dust.position.y *= 0.98
    }

    // flicker
    const flicker = 0.9 + Math.sin(t * 13.1) * 0.04 + Math.sin(t * 23.7) * 0.025
    world.key.intensity = 110 * flicker
    world.lampLights.forEach((l, i) => { l.intensity = 11 * (0.82 + Math.sin(t * 7 + i * 1.7) * 0.16) })
    world.engineCore.material.color.offsetHSL(0, 0, Math.sin(t * 3) * 0.002)
    world.railLights.forEach((m, i) => {
      m.material.color.offsetHSL(0, 0, Math.sin(t * 2.2 + i) * 0.0015)
    })

    if (world.bossSigil.visible) {
      world.bossSigil.rotation.z = t * 0.12
      world.bossSigil.material.opacity = 0.55 + Math.sin(t * 2.4) * 0.2
      world.bossBraziers.forEach(b => {
        b.flame.scale.y = 0.85 + Math.sin(t * 9 + b.phase) * 0.2
        b.flame.scale.x = 0.9 + Math.sin(t * 11 + b.phase) * 0.13
        b.light.intensity = 12 + Math.sin(t * 8 + b.phase) * 3
      })
    }

    // dust drift
    const pos = world.dust.geometry.attributes.position
    for (let i = 0; i < pos.count; i++) {
      const y = pos.getY(i)
      let ny = y + world.dustSpeed[i] * dt * (world.descent ? 8 : 1)
      if (ny > 32) ny = -2
      pos.setY(i, ny)
    }
    pos.needsUpdate = true
  }

  return world
}

import * as THREE from 'three'

const SKIN = 0xc7a37a

function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.62, metalness: 0.12, ...opts })
}

function mesh(geo, material, x = 0, y = 0, z = 0, parent) {
  const m = new THREE.Mesh(geo, material)
  m.position.set(x, y, z)
  m.castShadow = true
  m.receiveShadow = true
  if (parent) parent.add(m)
  return m
}

function glowSprite(texture, color, size, opacity = 0.8) {
  const material = new THREE.SpriteMaterial({
    map: texture,
    color,
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  })
  const sprite = new THREE.Sprite(material)
  sprite.scale.set(size, size, 1)
  return sprite
}

// ---------------------------------------------------------------- hunter
export function createHunter(glowTexture) {
  const root = new THREE.Group()
  const body = new THREE.Group()
  root.add(body)

  const leather = mat(0x252c35, { roughness: 0.78, metalness: 0.08 })
  const leatherDark = mat(0x12171d, { roughness: 0.82 })
  const cloth = mat(0x5b1d26, { roughness: 0.9 })
  const metal = mat(0x60646a, { metalness: 0.85, roughness: 0.33 })
  const skin = mat(SKIN, { roughness: 0.85 })

  const coat = mesh(new THREE.CylinderGeometry(0.34, 0.54, 1.08, 10), leather, 0, 1.16, 0, body)
  coat.scale.z = 0.82
  mesh(new THREE.CylinderGeometry(0.55, 0.6, 0.12, 10), leatherDark, 0, 0.64, 0, body)
  // chest rig
  mesh(new THREE.BoxGeometry(0.5, 0.44, 0.34), leatherDark, 0, 1.52, 0.02, body)
  const strapL = mesh(new THREE.BoxGeometry(0.07, 0.56, 0.05), cloth, -0.18, 1.53, 0.19, body)
  strapL.rotation.z = 0.42
  const strapR = mesh(new THREE.BoxGeometry(0.07, 0.56, 0.05), cloth, 0.18, 1.53, 0.19, body)
  strapR.rotation.z = -0.42
  mesh(new THREE.BoxGeometry(0.12, 0.1, 0.08), metal, 0, 1.44, 0.25, body)

  // shoulder mantle
  const mantle = mesh(new THREE.CylinderGeometry(0.52, 0.34, 0.25, 10, 1, true), leatherDark, 0, 1.68, 0, body)
  mantle.scale.z = 0.85
  // scarf
  mesh(new THREE.TorusGeometry(0.245, 0.07, 6, 12), cloth, 0, 1.82, 0, body).rotation.x = Math.PI / 2

  // head + hat
  const head = mesh(new THREE.SphereGeometry(0.225, 12, 10), skin, 0, 2.0, 0.01, body)
  head.scale.set(0.9, 1.05, 0.9)
  mesh(new THREE.SphereGeometry(0.035, 6, 6), mat(0x161616), -0.08, 2.02, 0.19, body)
  mesh(new THREE.SphereGeometry(0.035, 6, 6), mat(0x161616), 0.08, 2.02, 0.19, body)
  const brim = mesh(new THREE.CylinderGeometry(0.46, 0.46, 0.035, 16), leatherDark, 0, 2.16, 0, body)
  brim.rotation.z = 0.035
  const crown = mesh(new THREE.CylinderGeometry(0.27, 0.31, 0.34, 12), leatherDark, 0, 2.32, 0, body)
  crown.rotation.z = 0.035
  mesh(new THREE.CylinderGeometry(0.315, 0.315, 0.045, 12), cloth, 0, 2.16, 0, body)
  // coat tails
  for (let i = -1; i <= 1; i++) {
    const tail = mesh(new THREE.BoxGeometry(0.22, 0.78, 0.06), leather, i * 0.2, 0.7, -0.35, body)
    tail.rotation.x = -0.16
    tail.rotation.z = i * 0.08
  }

  // legs
  const legs = []
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group()
    pivot.position.set(side * 0.2, 0.78, 0)
    body.add(pivot)
    const thigh = mesh(new THREE.BoxGeometry(0.2, 0.62, 0.23), leatherDark, 0, -0.3, 0, pivot)
    thigh.scale.z = 0.9
    const boot = mesh(new THREE.BoxGeometry(0.24, 0.28, 0.38), mat(0x0c0e11, { roughness: 0.66, metalness: 0.35 }), 0, -0.72, 0.06, pivot)
    boot.rotation.x = 0.06
    legs.push({ pivot, side })
  }

  // arms
  const arms = []
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group()
    pivot.position.set(side * 0.46, 1.6, 0)
    body.add(pivot)
    const upper = mesh(new THREE.BoxGeometry(0.17, 0.46, 0.2), leather, 0, -0.19, 0, pivot)
    upper.rotation.x = 0.2
    const forearm = mesh(new THREE.BoxGeometry(0.15, 0.38, 0.17), leatherDark, side * 0.02, -0.5, 0.19, pivot)
    forearm.rotation.x = -0.9
    const glove = mesh(new THREE.SphereGeometry(0.11, 8, 8), mat(0x191c20, { roughness: 0.8 }), side * 0.03, -0.56, 0.4, pivot)
    arms.push({ pivot, side, glove })
  }

  // revolver held at chest height, pointing +Z
  const gun = new THREE.Group()
  gun.position.set(0.05, 1.34, 0.3)
  body.add(gun)
  mesh(new THREE.BoxGeometry(0.13, 0.19, 0.36), mat(0x2b3038, { metalness: 0.9, roughness: 0.28 }), 0, 0, 0.12, gun)
  const barrel = mesh(new THREE.CylinderGeometry(0.052, 0.052, 0.48, 8), mat(0x4b515a, { metalness: 0.95, roughness: 0.2 }), 0, 0.045, 0.44, gun)
  barrel.rotation.x = Math.PI / 2
  const chamber = mesh(new THREE.CylinderGeometry(0.095, 0.095, 0.1, 12), mat(0x5a3a1b, { metalness: 0.8, roughness: 0.3 }), 0, 0, 0.15, gun)
  chamber.rotation.x = Math.PI / 2
  const chamberGlow = mesh(new THREE.CylinderGeometry(0.056, 0.056, 0.106, 8), new THREE.MeshBasicMaterial({ color: 0xffc36b }), 0, 0, 0.15, gun)
  chamberGlow.rotation.x = Math.PI / 2
  const grip = mesh(new THREE.BoxGeometry(0.12, 0.24, 0.12), mat(0x3a2317, { roughness: 0.8 }), 0, -0.18, 0.02, gun)
  grip.rotation.x = -0.22
  const muzzle = new THREE.Object3D()
  muzzle.position.set(0, 0.045, 0.7)
  gun.add(muzzle)

  const muzzleGlow = glowSprite(glowTexture, 0xffb14e, 0.35, 0)
  muzzleGlow.position.copy(muzzle.position)
  gun.add(muzzleGlow)

  // soft ground shadow accent (helps on top of real shadows)
  const blob = new THREE.Mesh(
    new THREE.CircleGeometry(0.55, 20),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.35, depthWrite: false })
  )
  blob.rotation.x = -Math.PI / 2
  blob.position.y = 0.02
  root.add(blob)

  return {
    root,
    body,
    legs,
    arms,
    gun,
    muzzle,
    muzzleGlow,
    chamberGlow,
    recoil: 0,
    walkPhase: 0,
    animate(dt, moving, speed, t) {
      this.walkPhase += dt * (moving ? speed * 1.7 : 1.2)
      const stride = moving ? Math.min(1.2, speed / 5.5) : 0
      for (const leg of legs) {
        const s = Math.sin(this.walkPhase + (leg.side > 0 ? Math.PI : 0))
        leg.pivot.rotation.x = s * 0.58 * stride
        leg.pivot.position.y = 0.78 + Math.abs(s) * 0.03 * stride
      }
      const bob = Math.abs(Math.sin(this.walkPhase)) * 0.045 * stride
      body.position.y = bob + Math.sin(t * 2.2) * 0.006
      body.rotation.z = Math.sin(this.walkPhase) * 0.03 * stride
      for (const arm of arms) {
        arm.pivot.rotation.x = -0.12 + Math.sin(this.walkPhase * 0.5 + arm.side) * 0.04 * stride
      }
      this.recoil = Math.max(0, this.recoil - dt * 7)
      gun.position.z = 0.3 - this.recoil * 0.08
      gun.rotation.x = this.recoil * 0.22
      muzzleGlow.material.opacity = Math.max(0, this.recoil - 0.3) * 1.2
      this.chamberGlow.material.color.setHSL(0.1, 1, 0.55 + Math.sin(t * 4) * 0.08)
      blob.material.opacity = 0.3
    }
  }
}

// ---------------------------------------------------------------- enemies
const enemyPalettes = {
  husk: { body: 0x3b4149, dark: 0x1c2025, eye: 0xff7b32, eye2: 0xffcf74 },
  crawler: { body: 0x3d2f3e, dark: 0x211826, eye: 0xff3366, eye2: 0xffa3b5 },
  brute: { body: 0x3d3130, dark: 0x1f1717, eye: 0xff5b2b, eye2: 0xffbe74 },
  wretch: { body: 0x2c3d3b, dark: 0x142421, eye: 0x5df0d5, eye2: 0xbcfff4 }
}

function addHitbox(root, hitboxes, radius, y, part, scale = [1, 1, 1]) {
  const m = new THREE.Mesh(
    new THREE.SphereGeometry(radius, 8, 8),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false, colorWrite: false })
  )
  m.position.y = y
  m.scale.set(...scale)
  m.userData.hitPart = part
  root.add(m)
  hitboxes.push(m)
  return m
}

export function createEnemy(type, glowTexture) {
  const palette = enemyPalettes[type]
  const root = new THREE.Group()
  const rig = new THREE.Group()
  root.add(rig)
  const hitboxes = []
  const flashMats = []
  const eyeMats = []

  const bodyMat = mat(palette.body, { roughness: 0.76, metalness: 0.18 })
  const darkMat = mat(palette.dark, { roughness: 0.86, metalness: 0.15 })
  const boneMat = mat(0x8b8170, { roughness: 0.84 })
  const eyeMat = new THREE.MeshBasicMaterial({ color: palette.eye })
  flashMats.push(bodyMat, darkMat)
  eyeMats.push(eyeMat)

  const eyes = (parent, x, y, z, size = 0.055) => {
    const e1 = mesh(new THREE.SphereGeometry(size, 6, 6), eyeMat, -x, y, z, parent)
    const e2 = mesh(new THREE.SphereGeometry(size, 6, 6), eyeMat, x, y, z, parent)
    eyes.forEach?.(() => {})
    return [e1, e2]
  }

  const parts = { head: null, arms: [], legs: [], jaw: null, eyeGlow: [] }

  if (type === 'husk') {
    const torso = mesh(new THREE.CylinderGeometry(0.24, 0.38, 1.05, 8), bodyMat, 0, 1.42, 0, rig)
    torso.scale.z = 0.72
    mesh(new THREE.CylinderGeometry(0.39, 0.44, 0.2, 8), darkMat, 0, 0.9, 0, rig)
    const ribs = mesh(new THREE.CylinderGeometry(0.4, 0.34, 0.62, 8, 1, true), darkMat, 0, 1.6, 0, rig)
    ribs.scale.z = 0.74
    const neck = mesh(new THREE.CylinderGeometry(0.09, 0.11, 0.22, 6), boneMat, 0, 2.08, 0, rig)
    neck.rotation.z = 0.08
    const head = mesh(new THREE.SphereGeometry(0.22, 9, 8), bodyMat, 0, 2.3, 0.02, rig)
    head.scale.set(0.82, 1.02, 0.9)
    parts.head = head
    const jaw = mesh(new THREE.BoxGeometry(0.22, 0.1, 0.24), darkMat, 0, 2.19, 0.13, rig)
    jaw.rotation.x = 0.16
    parts.jaw = jaw
    const e = []
    e.push(mesh(new THREE.SphereGeometry(0.05, 6, 6), eyeMat, -0.08, 2.34, 0.18, rig))
    e.push(mesh(new THREE.SphereGeometry(0.05, 6, 6), eyeMat, 0.08, 2.34, 0.18, rig))
    parts.eyeGlow = e
    for (const side of [-1, 1]) {
      const arm = new THREE.Group()
      arm.position.set(side * 0.36, 1.86, 0)
      rig.add(arm)
      const upper = mesh(new THREE.BoxGeometry(0.13, 0.6, 0.14), darkMat, 0, -0.26, 0, arm)
      upper.rotation.z = side * 0.08
      const fore = mesh(new THREE.BoxGeometry(0.11, 0.56, 0.12), boneMat, side * 0.04, -0.74, 0.1, arm)
      fore.rotation.x = -0.32
      for (let c = 0; c < 3; c++) {
        const claw = mesh(new THREE.ConeGeometry(0.035, 0.28, 5), boneMat, side * 0.04 + (c - 1) * 0.07, -1.05, 0.24, arm)
        claw.rotation.x = 2.7
      }
      parts.arms.push(arm)
      const leg = new THREE.Group()
      leg.position.set(side * 0.18, 0.86, 0)
      rig.add(leg)
      mesh(new THREE.BoxGeometry(0.16, 0.72, 0.18), darkMat, 0, -0.36, 0, leg)
      mesh(new THREE.BoxGeometry(0.2, 0.16, 0.36), bodyMat, 0, -0.78, 0.08, leg)
      parts.legs.push(leg)
    }
    addHitbox(root, hitboxes, 0.56, 1.35, 'body', [1, 1.55, 0.85])
    addHitbox(root, hitboxes, 0.28, 2.3, 'head')
  }

  if (type === 'crawler') {
    const torso = mesh(new THREE.SphereGeometry(0.48, 10, 8), bodyMat, 0, 0.74, 0, rig)
    torso.scale.set(1.15, 0.72, 1.35)
    const back = mesh(new THREE.ConeGeometry(0.28, 0.9, 6), darkMat, 0, 1.08, -0.2, rig)
    back.rotation.x = -0.7
    const head = mesh(new THREE.SphereGeometry(0.27, 8, 7), bodyMat, 0, 0.82, 0.62, rig)
    head.scale.set(1, 0.8, 1.1)
    parts.head = head
    const jawMat = darkMat
    const jaw = mesh(new THREE.ConeGeometry(0.14, 0.36, 5), jawMat, 0, 0.68, 0.88, rig)
    jaw.rotation.x = 1.35
    parts.jaw = jaw
    parts.eyeGlow = [
      mesh(new THREE.SphereGeometry(0.055, 6, 6), eyeMat, -0.11, 0.92, 0.83, rig),
      mesh(new THREE.SphereGeometry(0.055, 6, 6), eyeMat, 0.11, 0.92, 0.83, rig)
    ]
    for (const side of [-1, 1]) {
      for (let i = 0; i < 2; i++) {
        const leg = new THREE.Group()
        leg.position.set(side * 0.45, 0.62, i === 0 ? 0.35 : -0.35)
        rig.add(leg)
        const upper = mesh(new THREE.BoxGeometry(0.1, 0.5, 0.1), darkMat, side * 0.15, -0.15, 0, leg)
        upper.rotation.z = side * 0.8
        mesh(new THREE.BoxGeometry(0.09, 0.46, 0.09), boneMat, side * 0.36, -0.5, 0, leg)
        leg.rotation.x = (i === 0 ? 1 : -1) * 0.12
        parts.legs.push({ pivot: leg, side, index: i })
      }
    }
    addHitbox(root, hitboxes, 0.55, 0.78, 'body', [1.1, 0.75, 1.4])
    addHitbox(root, hitboxes, 0.25, 0.84, 'head')
  }

  if (type === 'brute') {
    const torso = mesh(new THREE.CylinderGeometry(0.62, 0.82, 1.5, 10), bodyMat, 0, 1.9, 0, rig)
    torso.scale.z = 0.85
    mesh(new THREE.CylinderGeometry(0.85, 0.9, 0.32, 10), darkMat, 0, 1.2, 0, rig)
    const chestPlate = mesh(new THREE.BoxGeometry(0.9, 0.8, 0.16), darkMat, 0, 2.18, 0.58, rig)
    chestPlate.rotation.x = 0.08
    const shoulderL = mesh(new THREE.SphereGeometry(0.42, 8, 8), darkMat, -0.86, 2.5, 0, rig)
    shoulderL.scale.set(1.1, 0.8, 1)
    const shoulderR = shoulderL.clone()
    shoulderR.position.x = 0.86
    rig.add(shoulderR)
    const head = mesh(new THREE.SphereGeometry(0.27, 8, 7), bodyMat, 0, 2.86, 0.08, rig)
    head.scale.set(0.9, 0.8, 1)
    parts.head = head
    const jaw = mesh(new THREE.BoxGeometry(0.3, 0.12, 0.3), darkMat, 0, 2.73, 0.25, rig)
    parts.jaw = jaw
    const hornMat = mat(0x8c7b63, { roughness: 0.75 })
    for (const side of [-1, 1]) {
      const horn = mesh(new THREE.ConeGeometry(0.1, 0.6, 6), hornMat, side * 0.19, 3.08, 0.05, rig)
      horn.rotation.z = side * -0.55
      horn.rotation.x = -0.18
    }
    parts.eyeGlow = [
      mesh(new THREE.SphereGeometry(0.055, 6, 6), eyeMat, -0.1, 2.9, 0.3, rig),
      mesh(new THREE.SphereGeometry(0.055, 6, 6), eyeMat, 0.1, 2.9, 0.3, rig)
    ]
    for (const side of [-1, 1]) {
      const arm = new THREE.Group()
      arm.position.set(side * 0.92, 2.42, 0)
      rig.add(arm)
      const upper = mesh(new THREE.BoxGeometry(0.32, 0.86, 0.34), darkMat, 0, -0.36, 0, arm)
      upper.rotation.z = side * 0.12
      const fore = mesh(new THREE.BoxGeometry(0.3, 0.74, 0.32), bodyMat, side * 0.08, -0.99, 0.08, arm)
      const fist = mesh(new THREE.SphereGeometry(0.32, 8, 8), darkMat, side * 0.1, -1.38, 0.12, arm)
      fist.scale.set(1.15, 0.9, 1.2)
      parts.arms.push(arm)
      const leg = new THREE.Group()
      leg.position.set(side * 0.34, 1.2, 0)
      rig.add(leg)
      mesh(new THREE.BoxGeometry(0.33, 0.8, 0.38), darkMat, 0, -0.4, 0, leg)
      mesh(new THREE.BoxGeometry(0.38, 0.22, 0.58), bodyMat, 0, -0.84, 0.1, leg)
      parts.legs.push({ pivot: leg, side, index: 0 })
    }
    const spikeMat = mat(0x6a6255, { metalness: 0.4, roughness: 0.7 })
    for (let i = 0; i < 4; i++) {
      const spike = mesh(new THREE.ConeGeometry(0.12, 0.55, 5), spikeMat, (i - 1.5) * 0.25, 2.55, -0.54, rig)
      spike.rotation.x = -2.2
    }
    addHitbox(root, hitboxes, 0.95, 1.9, 'body', [1, 1.55, 0.9])
    addHitbox(root, hitboxes, 0.3, 2.88, 'head')
  }

  if (type === 'wretch') {
    const robe = mesh(new THREE.ConeGeometry(0.62, 1.65, 9), bodyMat, 0, 1.38, 0, rig)
    robe.rotation.y = 0.4
    const shoulders = mesh(new THREE.SphereGeometry(0.42, 8, 8), darkMat, 0, 1.95, 0, rig)
    shoulders.scale.set(1.2, 0.55, 0.85)
    const hood = mesh(new THREE.SphereGeometry(0.34, 9, 8, 0, Math.PI * 2, 0, Math.PI * 0.78), darkMat, 0, 2.18, 0.02, rig)
    hood.rotation.x = 0.2
    const face = mesh(new THREE.SphereGeometry(0.19, 8, 6), mat(0x080b0c, { roughness: 1 }), 0, 2.12, 0.24, rig)
    parts.head = face
    parts.eyeGlow = [
      mesh(new THREE.SphereGeometry(0.05, 6, 6), eyeMat, -0.08, 2.17, 0.34, rig),
      mesh(new THREE.SphereGeometry(0.05, 6, 6), eyeMat, 0.08, 2.17, 0.34, rig)
    ]
    const mouth = mesh(new THREE.BoxGeometry(0.18, 0.08, 0.04), eyeMat, 0, 2.02, 0.36, rig)
    parts.jaw = mouth
    for (const side of [-1, 1]) {
      const arm = new THREE.Group()
      arm.position.set(side * 0.46, 1.92, 0.02)
      rig.add(arm)
      const sleeve = mesh(new THREE.ConeGeometry(0.16, 0.8, 6, 1, true), darkMat, side * 0.06, -0.34, 0.08, arm)
      sleeve.rotation.z = side * 0.25
      const hand = mesh(new THREE.SphereGeometry(0.09, 6, 6), eyeMat, side * 0.12, -0.74, 0.16, arm)
      hand.scale.set(0.7, 0.7, 1.5)
      parts.arms.push(arm)
    }
    const aura = glowSprite(glowTexture, palette.eye, 1.7, 0.16)
    aura.position.y = 1.5
    rig.add(aura)
    addHitbox(root, hitboxes, 0.62, 1.5, 'body', [1, 1.55, 0.9])
    addHitbox(root, hitboxes, 0.27, 2.15, 'head')
  }

  const eyeSprites = parts.eyeGlow.map(e => {
    const s = glowSprite(glowTexture, palette.eye, 0.45, 0.55)
    s.position.copy(e.position)
    rig.add(s)
    return s
  })

  return {
    type,
    root,
    rig,
    hitboxes,
    parts,
    eyeSprites,
    eyeMats,
    flashMats,
    baseColors: flashMats.map(m => m.color.clone()),
    flash: 0,
    hover: type === 'wretch',
    animate(dt, t, speed, moving) {
      this.flash = Math.max(0, this.flash - dt * 5)
      flashMats.forEach((m, i) => {
        m.emissive.setRGB(this.flash * 0.9, this.flash * 0.55, this.flash * 0.25)
        m.emissiveIntensity = this.flash * 1.6
      })
      const walk = t * (moving ? speed * 2.2 : 1.4)
      if (type === 'husk') {
        parts.legs.forEach((leg, i) => {
          const s = Math.sin(walk + (i % 2 ? Math.PI : 0))
          leg.rotation.x = s * 0.55
        })
        parts.arms.forEach((arm, i) => {
          arm.rotation.x = Math.sin(walk + (i % 2 ? Math.PI : 0)) * 0.32 - 0.12
        })
        rig.position.y = Math.abs(Math.sin(walk)) * 0.035
        rig.rotation.z = Math.sin(walk * 0.5) * 0.02
      } else if (type === 'crawler') {
        parts.legs.forEach(leg => {
          leg.pivot.rotation.x = (leg.index === 0 ? 1 : -1) * 0.12 + Math.sin(walk * 1.5 + leg.side + leg.index) * 0.65
          leg.pivot.rotation.z = leg.side * 0.1
        })
        rig.position.y = Math.abs(Math.sin(walk * 1.5)) * 0.05
        parts.jaw.rotation.x = 1.35 + Math.sin(t * 8) * 0.18
      } else if (type === 'brute') {
        parts.legs.forEach((leg, i) => {
          leg.pivot.rotation.x = Math.sin(walk + (i % 2 ? Math.PI : 0)) * 0.4
        })
        parts.arms.forEach((arm, i) => {
          arm.rotation.x = Math.sin(walk + (i % 2 ? Math.PI : 0)) * 0.22 - 0.08
        })
        rig.rotation.z = Math.sin(walk * 0.5) * 0.025
      } else if (type === 'wretch') {
        rig.position.y = 0.16 + Math.sin(t * 1.8) * 0.12
        rig.rotation.z = Math.sin(t * 1.1) * 0.035
        parts.arms.forEach((arm, i) => {
          arm.rotation.x = Math.sin(t * 1.6 + i) * 0.14
          arm.rotation.z = (i ? 1 : -1) * (0.1 + Math.sin(t * 2.4 + i) * 0.05)
        })
        parts.jaw.scale.x = 1 + Math.sin(t * 5) * 0.12
      }
      eyeSprites.forEach((s, i) => {
        s.material.opacity = 0.38 + Math.sin(t * 4 + i) * 0.16
        s.scale.setScalar(0.38 + Math.sin(t * 3 + i) * 0.05)
      })
    }
  }
}

// ---------------------------------------------------------------- boss
export function createBoss(glowTexture) {
  const root = new THREE.Group()
  const rig = new THREE.Group()
  root.add(rig)
  const hitboxes = []
  const flashMats = []
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0xff2138 })

  const skin = mat(0x2d1519, { roughness: 0.7, metalness: 0.2 })
  const dark = mat(0x130a0d, { roughness: 0.8, metalness: 0.25 })
  const bone = mat(0x8e7562, { roughness: 0.72 })
  const metal = mat(0x45343a, { metalness: 0.8, roughness: 0.35 })
  flashMats.push(skin, dark)

  const torso = mesh(new THREE.SphereGeometry(1.55, 14, 12), skin, 0, 3.15, 0, rig)
  torso.scale.set(1.35, 1.15, 0.95)
  const belly = mesh(new THREE.SphereGeometry(1.05, 12, 10), dark, 0, 2.45, 0.34, rig)
  belly.scale.set(1.1, 0.85, 0.8)
  const collar = mesh(new THREE.TorusGeometry(0.95, 0.18, 8, 16), metal, 0, 3.9, 0, rig)
  collar.rotation.x = Math.PI / 2
  const chain = mesh(new THREE.TorusGeometry(0.78, 0.08, 6, 14), metal, 0, 3.72, 0.5, rig)
  chain.rotation.x = 0.2

  const head = mesh(new THREE.SphereGeometry(0.72, 12, 10), skin, 0, 4.25, 0.28, rig)
  head.scale.set(0.95, 0.86, 0.95)
  const brow = mesh(new THREE.BoxGeometry(1.15, 0.22, 0.4), dark, 0, 4.5, 0.58, rig)
  brow.rotation.x = -0.1
  const jaw = mesh(new THREE.BoxGeometry(0.82, 0.3, 0.6), dark, 0, 3.9, 0.55, rig)
  jaw.rotation.x = 0.2
  const teeth = []
  for (let i = 0; i < 5; i++) {
    const t = mesh(new THREE.ConeGeometry(0.07, 0.3, 5), bone, (i - 2) * 0.17, 4.02, 0.82, rig)
    t.rotation.x = Math.PI
    teeth.push(t)
  }
  const horns = []
  for (const side of [-1, 1]) {
    const horn = mesh(new THREE.ConeGeometry(0.22, 1.65, 7), bone, side * 0.62, 4.9, 0.18, rig)
    horn.rotation.z = side * -0.52
    horn.rotation.x = -0.22
    horns.push(horn)
    const horn2 = mesh(new THREE.ConeGeometry(0.12, 0.8, 6), bone, side * 1.1, 4.65, 0.05, rig)
    horn2.rotation.z = side * -1.1
  }
  const eyes = [
    mesh(new THREE.SphereGeometry(0.12, 7, 7), eyeMat, -0.3, 4.34, 0.88, rig),
    mesh(new THREE.SphereGeometry(0.12, 7, 7), eyeMat, 0.3, 4.34, 0.88, rig)
  ]
  for (const e of eyes) {
    const s = glowSprite(glowTexture, 0xff2138, 0.85, 0.6)
    s.position.copy(e.position)
    rig.add(s)
  }

  const sigilMat = new THREE.MeshBasicMaterial({
    color: 0xff4058,
    transparent: true,
    opacity: 0.85,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide
  })
  const sigil = new THREE.Mesh(new THREE.CircleGeometry(0.45, 20), sigilMat)
  sigil.position.set(0, 3.18, 1.36)
  rig.add(sigil)
  const sigilRing = new THREE.Mesh(new THREE.TorusGeometry(0.58, 0.035, 6, 24), sigilMat)
  sigilRing.position.set(0, 3.18, 1.34)
  rig.add(sigilRing)
  const chestLight = new THREE.PointLight(0xff3048, 12, 12, 1.8)
  chestLight.position.set(0, 3.2, 1.2)
  rig.add(chestLight)

  const arms = []
  for (const side of [-1, 1]) {
    const arm = new THREE.Group()
    arm.position.set(side * 1.85, 3.55, 0)
    rig.add(arm)
    const shoulder = mesh(new THREE.SphereGeometry(0.62, 10, 8), dark, 0, 0, 0, arm)
    const upper = mesh(new THREE.BoxGeometry(0.55, 1.55, 0.62), skin, side * 0.08, -0.85, 0, arm)
    upper.rotation.z = side * 0.16
    const fore = mesh(new THREE.BoxGeometry(0.48, 1.35, 0.5), skin, side * 0.2, -2.08, 0.18, arm)
    fore.rotation.x = -0.14
    const fist = mesh(new THREE.SphereGeometry(0.58, 9, 8), dark, side * 0.25, -2.85, 0.35, arm)
    fist.scale.set(1.2, 0.9, 1.25)
    const spike = mesh(new THREE.ConeGeometry(0.14, 0.5, 5), bone, side * 0.28, -2.85, 0.9, arm)
    spike.rotation.x = 1.4
    arms.push({ pivot: arm, side })
  }
  const legs = []
  for (const side of [-1, 1]) {
    const leg = new THREE.Group()
    leg.position.set(side * 0.75, 2.1, 0)
    rig.add(leg)
    const thigh = mesh(new THREE.BoxGeometry(0.62, 1.35, 0.72), skin, 0, -0.6, 0, leg)
    const shin = mesh(new THREE.BoxGeometry(0.54, 1.1, 0.6), dark, 0, -1.7, 0.16, leg)
    shin.rotation.x = -0.12
    const hoof = mesh(new THREE.BoxGeometry(0.66, 0.36, 0.95), metal, 0, -2.25, 0.38, leg)
    legs.push({ pivot: leg, side })
  }

  // spikes along back
  for (let i = 0; i < 5; i++) {
    const spike = mesh(new THREE.ConeGeometry(0.2, 1.0, 6), bone, 0, 4.4 - i * 0.32, -0.9 - i * 0.12, rig)
    spike.rotation.x = -0.85
  }

  const aura = glowSprite(glowTexture, 0xff2138, 6.5, 0.14)
  aura.position.y = 3
  rig.add(aura)

  addHitbox(root, hitboxes, 1.55, 2.8, 'body', [1.25, 1.25, 0.95])
  addHitbox(root, hitboxes, 0.62, 3.2, 'chest', [1.2, 1, 1])
  addHitbox(root, hitboxes, 0.68, 4.28, 'head')

  return {
    root,
    rig,
    hitboxes,
    flashMats,
    parts: { head, jaw, arms, legs, sigil, sigilRing, chestLight, eyes, horns },
    flash: 0,
    pose: 0,
    animate(dt, t, moving) {
      this.flash = Math.max(0, this.flash - dt * 4.5)
      flashMats.forEach(m => {
        m.emissive.setRGB(this.flash * 0.9, this.flash * 0.15, this.flash * 0.18)
        m.emissiveIntensity = this.flash * 1.9
      })
      this.pose += dt
      const breathe = Math.sin(t * 1.25) * 0.035
      rig.position.y = breathe
      torso.scale.y = 1.15 + breathe * 0.5
      head.rotation.x = Math.sin(t * 0.8) * 0.04
      jaw.rotation.x = 0.2 + Math.sin(t * 1.4) * 0.05
      sigil.rotation.z = t * 0.7
      sigilRing.rotation.z = -t * 1.2
      sigilMat.opacity = 0.62 + Math.sin(t * 3.1) * 0.2
      chestLight.intensity = 11 + Math.sin(t * 3.1) * 3
      arms.forEach((arm, i) => {
        arm.pivot.rotation.x = Math.sin(t * 1.1 + i * 2) * 0.06 - 0.05
        arm.pivot.rotation.z = arm.side * (0.08 + Math.sin(t * 0.8 + i) * 0.02)
      })
      if (!moving) {
        legs.forEach((leg, i) => { leg.pivot.rotation.x = Math.sin(t * 0.7 + i) * 0.02 })
      }
    }
  }
}

// ---------------------------------------------------------------- pickups / projectiles
export function createHealthPickup(glowTexture) {
  const group = new THREE.Group()
  const vialMat = new THREE.MeshStandardMaterial({
    color: 0x1a8a76,
    emissive: 0x3df0c5,
    emissiveIntensity: 1.3,
    metalness: 0.4,
    roughness: 0.2,
    transparent: true,
    opacity: 0.92
  })
  const vial = mesh(new THREE.CylinderGeometry(0.11, 0.13, 0.34, 8), vialMat, 0, 0.24, 0, group)
  const cap = mesh(new THREE.CylinderGeometry(0.075, 0.09, 0.11, 8), mat(0xd3bd92, { metalness: 0.8, roughness: 0.3 }), 0, 0.47, 0, group)
  const glow = glowSprite(glowTexture, 0x5df0d5, 1.1, 0.5)
  glow.position.y = 0.25
  group.add(glow)
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(0.28, 0.012, 4, 24),
    new THREE.MeshBasicMaterial({ color: 0x5df0d5, transparent: true, opacity: 0.65, blending: THREE.AdditiveBlending, depthWrite: false })
  )
  ring.rotation.x = Math.PI / 2
  ring.position.y = 0.03
  group.add(ring)
  return { group, vial, glow, ring }
}

export function createProjectileMesh(color = 0xff5a3c, size = 0.16, glowTexture) {
  const group = new THREE.Group()
  const core = new THREE.Mesh(
    new THREE.SphereGeometry(size, 8, 8),
    new THREE.MeshBasicMaterial({ color: 0xfff0d0 })
  )
  group.add(core)
  const shell = new THREE.Mesh(
    new THREE.SphereGeometry(size * 1.9, 8, 8),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.4, blending: THREE.AdditiveBlending, depthWrite: false })
  )
  group.add(shell)
  if (glowTexture) {
    const glow = glowSprite(glowTexture, color, size * 9, 0.65)
    group.add(glow)
  }
  return { group, core, shell }
}

import * as THREE from 'three'

function makeParticleSystem(scene, count, { size = 0.09, additive = true, opacity = 1 } = {}) {
  const positions = new Float32Array(count * 3)
  const colors = new Float32Array(count * 3)
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3))
  geometry.setDrawRange(0, 0)
  const material = new THREE.PointsMaterial({
    size,
    vertexColors: true,
    transparent: true,
    opacity,
    depthWrite: false,
    blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    sizeAttenuation: true
  })
  const points = new THREE.Points(geometry, material)
  points.frustumCulled = false
  points.renderOrder = 6
  scene.add(points)
  return {
    points,
    geometry,
    material,
    positions,
    colors,
    count,
    data: [],
    cursor: 0
  }
}

export class FX {
  constructor(scene, glowTexture) {
    this.scene = scene
    this.glowTexture = glowTexture
    this.sparks = makeParticleSystem(scene, 900, { size: 0.085, additive: true })
    this.debris = makeParticleSystem(scene, 500, { size: 0.075, additive: false })
    this.beams = []
    this.rings = []
    this.muzzle = null
    this.muzzleLight = new THREE.PointLight(0xffb14e, 0, 10, 2)
    scene.add(this.muzzleLight)
    this.shake = 0
    this.shakeDecay = 5
  }

  spawnParticle(system, p, v, color, life, gravity) {
    const i = system.cursor
    system.cursor = (system.cursor + 1) % system.count
    system.data[i] = { vx: v.x, vy: v.y, vz: v.z, life, maxLife: life, gravity }
    system.positions[i * 3] = p.x
    system.positions[i * 3 + 1] = p.y
    system.positions[i * 3 + 2] = p.z
    system.colors[i * 3] = color.r
    system.colors[i * 3 + 1] = color.g
    system.colors[i * 3 + 2] = color.b
    system.geometry.setDrawRange(0, system.count)
  }

  burst(position, opts = {}) {
    const {
      count = 12,
      color = 0xffc36b,
      speed = 5,
      drag = 0.94,
      life = 0.5,
      gravity = -9,
      spread = 1,
      up = 0.5,
      debris = false,
      size = 1
    } = opts
    const system = debris ? this.debris : this.sparks
    const c = new THREE.Color(color)
    for (let i = 0; i < count; i++) {
      const dir = new THREE.Vector3(
        (Math.random() - 0.5) * 2 * spread,
        Math.random() * up + 0.15,
        (Math.random() - 0.5) * 2 * spread
      ).normalize()
      const p = position.clone().add(new THREE.Vector3(
        (Math.random() - 0.5) * 0.2,
        (Math.random() - 0.5) * 0.2,
        (Math.random() - 0.5) * 0.2
      ))
      const v = dir.multiplyScalar(speed * (0.35 + Math.random() * 0.9))
      this.spawnParticle(system, p, v, c, life * (0.6 + Math.random() * 0.7), gravity)
    }
    system.material.size = Math.max(0.05, size * 0.09)
  }

  hit(position, color = 0xffd28a, head = false) {
    this.burst(position, {
      count: head ? 16 : 9,
      color,
      speed: head ? 7 : 5,
      life: 0.32,
      gravity: -13,
      up: 0.8
    })
    this.addRing(position.clone().setY(position.y + 0.05), {
      color,
      radius: head ? 0.45 : 0.3,
      end: head ? 0.9 : 0.55,
      life: 0.22,
      opacity: 0.65
    })
    this.shake = Math.max(this.shake, 0.035)
  }

  blood(position, color = 0x7d0f1d) {
    this.burst(position, {
      count: 11,
      color,
      speed: 4.5,
      life: 0.48,
      gravity: -15,
      up: 0.7,
      debris: true,
      size: 1.4
    })
    this.burst(position, {
      count: 4,
      color: 0xff4058,
      speed: 3,
      life: 0.25,
      gravity: -9,
      up: 0.5
    })
  }

  death(position, color = 0xff7b32, large = false) {
    this.burst(position, {
      count: large ? 55 : 26,
      color,
      speed: large ? 12 : 7,
      life: large ? 0.9 : 0.65,
      gravity: -7,
      up: 1.4,
      size: 1.3
    })
    this.burst(position, {
      count: large ? 35 : 16,
      color: 0x56121a,
      speed: large ? 9 : 5,
      life: 0.75,
      gravity: -16,
      up: 1,
      debris: true,
      size: 1.6
    })
    this.addRing(position.clone().setY(0.03), {
      color,
      radius: large ? 1 : 0.4,
      end: large ? 7 : 2.2,
      life: large ? 0.7 : 0.45,
      opacity: 0.8
    })
    this.shake = Math.max(this.shake, large ? 0.45 : 0.12)
  }

  spawnPortal(position, color = 0xff7b32) {
    this.addRing(position.clone().setY(0.04), { color, radius: 0.3, end: 1.8, life: 0.6, opacity: 0.9 })
    this.burst(position.clone().setY(0.4), {
      count: 16,
      color,
      speed: 2.4,
      life: 0.7,
      gravity: 1.5,
      up: 1.8
    })
  }

  muzzleFlash(position, direction, color = 0xffb14e) {
    if (!this.muzzle) {
      const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.glowTexture,
        color,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false
      }))
      sprite.scale.set(1.1, 1.1, 1)
      this.scene.add(sprite)
      this.muzzle = sprite
    }
    this.muzzle.position.copy(position).add(direction.clone().multiplyScalar(0.28))
    this.muzzle.material.opacity = 0.95
    this.muzzle.material.color.setHex(color)
    this.muzzle.scale.setScalar(0.8 + Math.random() * 0.45)
    this.muzzleLight.position.copy(position).add(direction.clone().multiplyScalar(0.4))
    this.muzzleLight.color.setHex(color)
    this.muzzleLight.intensity = 18
    this.burst(position, {
      count: 6,
      color,
      speed: 6.5,
      life: 0.18,
      gravity: -2,
      up: 0.4,
      spread: 0.45
    })
  }

  addBeam(from, to, color = 0xffe2a6) {
    let beam = this.beams.find(b => !b.active)
    if (!beam) {
      if (this.beams.length >= 24) return
      const material = new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 1,
        blending: THREE.AdditiveBlending,
        depthWrite: false
      })
      const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 1, 4, 1, true), material)
      mesh.renderOrder = 5
      this.scene.add(mesh)
      beam = { mesh, material, active: false, life: 0, maxLife: 1 }
      this.beams.push(beam)
    }
    const dir = to.clone().sub(from)
    const len = dir.length()
    beam.mesh.position.copy(from).add(dir.multiplyScalar(0.5))
    beam.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), to.clone().sub(from).normalize())
    beam.mesh.scale.set(1, len, 1)
    beam.material.color.setHex(color)
    beam.material.opacity = 0.85
    beam.mesh.visible = true
    beam.active = true
    beam.life = 0.075
    beam.maxLife = 0.075
  }

  addRing(position, { color = 0xff4058, radius = 0.5, end = 3, life = 0.5, opacity = 0.8, thickness = 0.12 } = {}) {
    let ring = this.rings.find(r => !r.active)
    if (!ring) {
      if (this.rings.length >= 20) return
      const material = new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending,
        depthWrite: false
      })
      const mesh = new THREE.Mesh(new THREE.RingGeometry(1 - thickness, 1, 64), material)
      mesh.rotation.x = -Math.PI / 2
      mesh.renderOrder = 4
      this.scene.add(mesh)
      ring = { mesh, material, active: false }
      this.rings.push(ring)
    }
    ring.mesh.position.copy(position)
    ring.mesh.scale.setScalar(radius)
    ring.mesh.visible = true
    ring.material.color.setHex(color)
    ring.material.opacity = opacity
    ring.active = true
    ring.life = life
    ring.maxLife = life
    ring.start = radius
    ring.end = end
    ring.opacity = opacity
  }

  banishColumn(position, color = 0xffd58d) {
    for (let i = 0; i < 5; i++) {
      const a = Math.random() * Math.PI * 2
      const r = Math.random() * 1.4
      const p = position.clone().add(new THREE.Vector3(Math.cos(a) * r, Math.random() * 0.2, Math.sin(a) * r))
      const v = new THREE.Vector3(Math.cos(a) * 0.5, 3.5 + Math.random() * 3.5, Math.sin(a) * 0.5)
      this.spawnParticle(this.sparks, p, v, new THREE.Color(color), 1.2, 1.4)
    }
  }

  update(dt) {
    const updateSystem = (system, drag, floorY) => {
      if (system.data.length === 0) return
      const pos = system.positions
      const col = system.colors
      let any = false
      for (let i = 0; i < system.count; i++) {
        const d = system.data[i]
        if (!d || d.life <= 0) {
          if (d) col[i * 3] = col[i * 3 + 1] = col[i * 3 + 2] = 0
          continue
        }
        any = true
        d.life -= dt
        d.vx *= Math.pow(drag, dt * 60)
        d.vz *= Math.pow(drag, dt * 60)
        d.vy += d.gravity * dt
        pos[i * 3] += d.vx * dt
        pos[i * 3 + 1] += d.vy * dt
        pos[i * 3 + 2] += d.vz * dt
        if (pos[i * 3 + 1] < floorY) {
          pos[i * 3 + 1] = floorY
          d.vy *= -0.25
          d.vx *= 0.5
          d.vz *= 0.5
        }
        const fade = Math.max(0, d.life / d.maxLife)
        col[i * 3] *= Math.pow(fade, 0.35)
        col[i * 3 + 1] *= Math.pow(fade, 0.35)
        col[i * 3 + 2] *= Math.pow(fade, 0.35)
      }
      if (!any) system.geometry.setDrawRange(0, 0)
      system.geometry.attributes.position.needsUpdate = true
      system.geometry.attributes.color.needsUpdate = true
    }
    updateSystem(this.sparks, 0.94, 0.03)
    updateSystem(this.debris, 0.9, 0.03)

    for (const beam of this.beams) {
      if (!beam.active) continue
      beam.life -= dt
      const f = Math.max(0, beam.life / beam.maxLife)
      beam.material.opacity = f
      if (beam.life <= 0) {
        beam.active = false
        beam.mesh.visible = false
      }
    }

    for (const ring of this.rings) {
      if (!ring.active) continue
      ring.life -= dt
      const t = 1 - Math.max(0, ring.life / ring.maxLife)
      const r = ring.start + (ring.end - ring.start) * (1 - Math.pow(1 - t, 2))
      ring.mesh.scale.setScalar(r)
      ring.material.opacity = ring.opacity * (1 - t)
      if (ring.life <= 0) {
        ring.active = false
        ring.mesh.visible = false
      }
    }

    if (this.muzzle) {
      this.muzzle.material.opacity = Math.max(0, this.muzzle.material.opacity - dt * 18)
    }
    this.muzzleLight.intensity = Math.max(0, this.muzzleLight.intensity - dt * 150)
    this.shake = Math.max(0, this.shake - dt * this.shakeDecay)
  }
}

